local config = {
  ui_story_5011_50110101_1_dialog_content = "Yang Mulia, mengenai pemberontakan geng di Umbraton...",
  ui_story_5011_50110101_2_dialog_content = "Para pemberontak itu menggunakan <color=#FFB400>Enhancer</color> untuk berubah menjadi Eclipsite dan melancarkan serangan hingga ke setiap sudut Umbraton.",
  ui_story_5011_50110101_3_dialog_content = "Mereka berencana membunuh Shadowlord Istvan, meledakkan dam, dan menghancurkan Umbraton.",
  ui_story_5011_50110101_4_dialog_content = "Kami sudah melacak sisa-sisa pemberontak itu hingga ke desa-desa di luar Umbraton. Akan ada pasukan yang diutus ke sana untuk menangkap mereka semua.",
  ui_story_5011_50110101_5_dialog_content = "Enhancer bisa mengubah Aurorian menjadi Eclipsite. Tak salah lagi, teknologi itu digunakan untuk kejahatan.",
  ui_story_5011_50110101_6_dialog_content = "Kemunculan obat ini secara luas pastilah konspirasi Eclipse.",
  ui_story_5011_50110101_7_dialog_content = "Kami juga menduga itu ada hubungannya dengan kerusuhan di kalangan bangsawan sepuluh tahun silam.",
  ui_story_5011_50110101_8_dialog_content = "Maksudmu, pemberontakan keluarga Gautier dan Pyrrhus.",
  ui_story_5011_50110101_9_dialog_content = "Benar.",
  ui_story_5011_50110101_10_dialog_content = "Lord, aku pernah berhadapan dengan Eclipsite jadi-jadian—Mirren Gautier, di Eraveil.",
  ui_story_5011_50110101_11_dialog_content = "Menurut hasil penyelidikanku, Eclipse-lah yang memerintahnya untuk menghasut keluarga Gautier dan Pyrrhus agar memberontak.",
  ui_story_5011_50110101_12_dialog_content = "Kami menduga transformasi Mirren Gautier ada kaitannya dengan Enhancer.",
  ui_story_5011_50110101_13_dialog_content = "Setelah menginterogasi pemimpin pemberontakan itu, kami juga mengetahui bahwa para bangsawan di kota kemungkinan ikut terlibat.",
  ui_story_5011_50110101_14_dialog_content = "Kami bisa mengetahui lebih banyak setelah menyelidiki para bangsawan itu...",
  ui_story_5011_50110101_15_dialog_content = "Bagaimana menurutmu, Elder <color=#FFB400>Lachon</color>?",
  ui_story_5011_50110101_16_dialog_content = "Apa kau punya bukti bahwa para bangsawan itu terlibat?",
  ui_story_5011_50110101_17_dialog_content = "Tidak, Elder Lachon. Kami harus menyelidikinya dulu—",
  ui_story_5011_50110101_18_dialog_content = "Dengan kata lain, kau bermaksud melakukan penyelidikan skala besar terhadap para bangsawan itu tanpa dasar?",
  ui_story_5011_50110101_19_dialog_content = "Kau mempertaruhkan kepentingan dan reputasi mereka.",
  ui_story_5011_50110101_20_dialog_content = "Atas nama seluruh bangsawan, aku menentang penyelidikan ini.",
  ui_story_5011_50110101_21_dialog_content = "Bahkan jika ingin melakukan penyelidikan, kita butuh rencana terperinci.",
  ui_story_5011_50110101_22_dialog_content = "Tapi—",
  ui_story_5011_50110101_23_dialog_content = "Cukup adil. Kita akan membahas penyelidikan atas para bangsawan itu lain kali.",
  ui_story_5011_50110101_24_dialog_content = "Saat ini, gereja memiliki masalah yang lebih penting untuk ditangani.",
  ui_story_5011_50110101_25_dialog_content = "Irridon, tolong perkenalkan utusan gereja itu.",
  ui_story_5011_50110101_26_dialog_content = "Tentu. Izinkan aku memperkenalkan <color=#FFB400>Hedy Bryte</color> kepada kalian.",
  ui_story_5011_50110101_27_dialog_content = "Gereja telah mengutus penyelidik dari Heretics Investigation Division.",
  ui_story_5011_50110101_28_dialog_content = "Dia bertanggung jawab untuk menyelidiki masalah Enhancer dan Eclipsite yang dimodifikasi.",
  ui_story_5011_50110101_29_dialog_content = "Selamat siang, Yang Mulia.",
  ui_story_5011_50110101_30_dialog_content = "Izinkan aku menyampaikan pendapat gereja.",
  ui_story_5011_50110101_31_dialog_content = "Bicaralah.",
  ui_story_5011_50110101_32_dialog_content = "Gereja selalu khawatir bahwa teknologi akan menjadi ancaman bagi Aurorian.",
  ui_story_5011_50110101_33_dialog_content = "Teknologi modifikasi ini hanya salah satu ancaman.",
  ui_story_5011_50110101_34_dialog_content = "Jika tidak dikendalikan, hasilnya akan membawa petaka.",
  ui_story_5011_50110101_35_dialog_content = "Illumina telah mengembangkan teknologi baru, dan gereja berharap agar Lumopolis—",
  ui_story_5011_50110101_36_dialog_content = "Ya. Mengingat perayaan kami, aku telah mengundang Illumina dan Northland untuk mempertimbangkan masalah ini.",
  ui_story_5011_50110101_37_dialog_content = "Aku menyadari pertimbangan gereja. Tapi, aku juga yakin bahwa itu akan... dikendalikan dengan sangat hati-hati.",
  ui_story_5011_50110101_38_dialog_content = "Kenapa City Lord Lumopolis mengundangku ke perayaan, ya? Aduh, entah aku harus bagaimana...",
  ui_story_5011_50110101_39_dialog_content = "Jangan khawatir, PlayerName. Dulu Shadowlord juga mengirimimu surat.",
  ui_story_5011_50110101_40_dialog_content = "Kita kan berteman baik dengan Carleen, jadi wajar saja kalau City Lord mengundangmu.",
  ui_story_5011_50110101_41_dialog_content = "Benarkah?",
  ui_story_5011_50110101_42_dialog_content = "Sedang apa kalian?",
  ui_story_5011_50110101_43_dialog_content = "Aku sedang memperbaiki Colossus-mu, tapi kalian justru bercanda di sini?",
  ui_story_5011_50110101_44_dialog_content = "Sama sekali tidak, Gronru! Aku dapat surat penting.",
  ui_story_5011_50110101_45_dialog_content = "Surat macam apa?",
  ui_story_5011_50110101_46_dialog_content = "Undangan dari Lumopolis.",
  ui_story_5011_50110101_47_dialog_content = "Undangan dari Lumopolis? Oh, itu pasti undangan untuk menghadiri perayaan.",
  ui_story_5011_50110101_48_dialog_content = "Kau mendapat reputasi yang baik karena mengejar Schummer ke Lumopolis dengan Colossus.",
  ui_story_5011_50110101_49_dialog_content = "Tentu saja mereka mengundangmu.",
  ui_story_5011_50110101_50_dialog_content = "Tapi, menurutku... perayaan di Lumopolis membosankan.",
  ui_story_5011_50110101_51_dialog_content = "Perayaannya tidak semengasyikkan Colossus! Aku sudah memasang <color=#FFB400>komponen Simulation Room</color> untukmu.",
  ui_story_5011_50110101_52_dialog_content = "Hah? Sudah?",
  ui_story_5011_50110101_53_dialog_content = "Benar, aku bahkan sudah menyesuaikan medan tempur simulasinya—",
  ui_story_5011_50110101_54_dialog_content = "Hah? Kenapa tidak merespons, sih?",
  ui_story_5011_50110101_55_dialog_content = "Hmm, pasti ada kesalahan di suatu tempat. Biar kucari!",
  ui_story_5011_50110101_56_dialog_content = "Oh, ada tim investigasi yang akan pergi ke Lumopolis.",
  ui_story_5011_50110101_57_dialog_content = "Kenapa kau tidak ikut saja dengan mereka?",
  ui_story_5011_50110101_58_dialog_content = "Dengan begitu, aku bisa melanjutkan perbaikan pada Colossus saat kau pergi.",
  ui_story_5011_50110101_59_dialog_content = "Tapi—",
  ui_story_5011_50110101_60_dialog_content = "Jangan cemas. Biar kuhubungi mereka. Aku yakin kalian saling mengenal.",
  ui_story_5011_50110101_61_dialog_content = "Yah, apa boleh buat... Kau memang sangat suka mengutak-atik Colossus, ya.",
  ui_story_5011_50110101_62_dialog_content = "Akhirnya! Tadinya kupikir kau tak akan datang.",
  ui_story_5011_50110101_63_dialog_content = "Navigator PlayerName, Lieutenant Vice—Sheriff Illumina Cordy siap membantu.",
  ui_story_5011_50110101_64_dialog_content = "Hihi! Vida juga siap membantu!",
  ui_story_5011_50110101_65_dialog_content = "Kami baru saja mendengar dari Tech Officer Gronru bahwa kami punya tugas tambahan.",
  ui_story_5011_50110101_66_dialog_content = "PlayerName, kami akan mengawalmu ke Lumopolis. Kau akan aman bersama kami!",
  ui_story_5011_50110101_67_dialog_content = "Mengawal? Itu sedikit terlalu...",
  ui_story_5011_50110101_68_dialog_content = "Sama sekali tidak. Lagi pula, kau kan orang penting.",
  ui_story_5011_50110101_69_dialog_content = "Kau bisa memiloti Colossus dan menavigasi pertempuran. Nah, karena itulah kau jadi orang penting untuk Illumina dan Lumopolis.",
  ui_story_5011_50110101_70_dialog_content = "Memangnya aku dipromosikan untuk naik pangkat atau semacamnya? Rasanya aneh... tapi terima kasih, ya.",
  ui_story_5011_50110101_71_dialog_content = "Haha, bukan masalah! Ayo kita berangkat!",
  ui_story_5011_50110201_1_dialog_content = "Kita sudah hampir tiba di stasiun transportasi. Ada beberapa perbekalan yang harus kami ambil di sana.",
  ui_story_5011_50110201_2_dialog_content = "Stasiun transportasi... Kita tidak langsung pergi ke Lumopolis, ya?",
  ui_story_5011_50110201_3_dialog_content = "Kita hanya bisa mencapai Lumopolis dengan naik pesawat dari Umbraton.",
  ui_story_5011_50110201_4_dialog_content = "Karena Illumina cukup jauh dari Umbraton, pasti ada stasiun transportasi di sepanjang jalan.",
  ui_story_5011_50110201_5_dialog_content = "Oh, tentu saja. Karena sering naik Colossus, kau jadi kurang familier dengan transportasi darat.",
  ui_story_5011_50110201_6_dialog_content = "Benar. Bisakah kita berhenti untuk beristirahat sesampainya di sana?",
  ui_story_5011_50110201_7_dialog_content = "Tentu saja. Kau tidak nyaman dengan perjalanannya, ya?",
  ui_story_5011_50110201_8_dialog_content = "Oh, tidak apa-apa, kok. Aku hanya ingin berdiri dan meregangkan kaki.",
  ui_story_5011_50110201_9_dialog_content = "Panggilan kepada tim investigasi!",
  ui_story_5011_50110201_10_dialog_content = "Patroli Lumopolis bertempur dengan Eclipsite di dekat stasiun!",
  ui_story_5011_50110201_11_dialog_content = "Stasiun transportasi itu sedang ditutup untuk sementara.",
  ui_story_5011_50110201_12_dialog_content = "Eclipsite? Wah, beruntung sekali. Misi kami di sini memang untuk menyelidiki para Eclipsite itu.",
  ui_story_5011_50110201_13_dialog_content = "Prajurit, kami akan melanjutkan perjalanan ke stasiun transportasi dan membantu menyingkirkan para Eclipsite.",
  ui_story_5011_50110201_14_dialog_content = "Siap, laksanakan.",
  ui_story_5011_50110201_15_dialog_content = "Cordy, apa yang dilakukan patroli Lumopolis di sini?",
  ui_story_5011_50110201_16_dialog_content = "Kita jauh dari Umbraton. Ini jelas-jelas bukan wilayah patroli biasa mereka.",
  ui_story_5011_50110201_17_dialog_content = "Yah, ini karena ada perayaan yang sedang diselenggarakan, dan ada banyak orang yang berkunjung ke Lumopolis sekarang.",
  ui_story_5011_50110201_18_dialog_content = "Carleen pernah bilang...",
  ui_story_5011_50110201_19_dialog_content = "Lumopolis akan memperluas cakupan patrolinya untuk memastikan keamanan kedatangan tamunya.",
  ui_story_5011_50110201_20_dialog_content = "Graaah—!",
  ui_story_5011_50110201_21_dialog_content = "Vice, aku merasakan Eclipsite di depan sana.",
  ui_story_5011_50110201_22_dialog_content = "Seseorang yang kita kenal juga ada di sana.",
  ui_story_5011_50110201_23_dialog_content = "Kami dengar pasukan prajurit Illumina sedang dalam perjalanan.",
  ui_story_5011_50110201_24_dialog_content = "Tak kusangka kau dan Vice-lah yang diutus.",
  ui_story_5011_50110201_25_dialog_content = "Sedang apa kau di sini, Pittman?",
  ui_story_5011_50110201_26_dialog_content = "Kami memburu para Eclipsite jadi-jadian. Tapi, di luar dugaan kami, situasinya justru makin rumit.",
  ui_story_5011_50110201_27_dialog_content = "Eclipsite jadi-jadian?",
  ui_story_5011_50110201_28_dialog_content = "Benar. Merekalah yang tersisa dari pemberontak Umbraton.",
  ui_story_5011_50110201_29_dialog_content = "Pemberontak Umbraton?",
  ui_story_5011_50110201_30_dialog_content = "Lieutenant Vice, bisakah kau memperkenalkan orang-orang dari Lumopolis ini? Sepertinya kau mengenal baik mereka.",
  ui_story_5011_50110201_31_dialog_content = "Bukan masalah. Ini Pittman, hakim Lumopolis.",
  ui_story_5011_50110201_32_dialog_content = "Dulu dia membantuku mengalahkan Eclipsite di Eraveil, dan aku membantunya menyelidiki salah satu kasusnya. Bisa dibilang kami berteman.",
  ui_story_5011_50110201_33_dialog_content = "Lalu, siapa yang satunya?",
  ui_story_5011_50110201_34_dialog_content = "Wanita itu memandang kami... dengan penuh minat sejak tadi.",
  ui_story_5011_50110201_35_dialog_content = "Oh, ini <color=#FFB400>Hedy</color>, atasanku.",
  ui_story_5011_50110201_36_dialog_content = "Jangan hiraukan aku.",
  ui_story_5011_50110201_37_dialog_content = "Pittman, aku yakin kau bisa menyingkirkan para Eclipsite ini.",
  ui_story_5011_50110201_38_dialog_content = "Aku akan membantu jika diperlukan.",
  ui_story_5011_50110201_38X_dialog_content = "Ingat, kalau kalian menemukan Enhancer, serahkan saja kepadaku.",
  ui_story_5011_50110201_38X1_dialog_content = "Lalu, para Eclipsite itu harus diberantas tuntas, paham?",
  ui_story_5011_50110201_39_dialog_content = "Baik.",
  ui_story_5011_50110201_40_dialog_content = "Vice, bisakah kau meminta bantuan semua orang untuk membantu kami memburu Eclipsite?",
  ui_story_5011_50110201_41_dialog_content = "Mereka melarikan diri ke berbagai arah, dan mungkin bisa membahayakan desa-desa di sekitar sini.",
  ui_story_5011_50110201_42_dialog_content = "Siap!",
  ui_story_5011_50110201_43_dialog_content = "Semua penjaga, ikut aku! Jangan sampai satu pun lolos!",
  ui_story_5011_50110201_44_dialog_content = "Siap, Pak!",
  ui_story_5011_50110202_1_dialog_content = "Grrrr!",
  ui_story_5011_50110202_2_dialog_content = "Mereka kabur!",
  ui_story_5011_50110202_3_dialog_content = "Jangan sampai ini terjadi.",
  ui_story_5011_50110202_4_dialog_content = "Minggir. Biar kutangani mereka.",
  ui_story_5011_50110202_5_dialog_content = "Tapi—kami sedang bertempur! Jangan bertindak ceroboh!",
  ui_story_5011_50110202_6_dialog_content = "Maaf, tapi sepertinya kau tidak paham situasinya.",
  ui_story_5011_50110202_7_dialog_content = "Para Eclipsite itu akan menerobos kepungan. Kita harus menyingkirkan mereka sekarang.",
  ui_story_5011_50110202_8_dialog_content = "Perintahkan prajuritmu untuk minggir. Kalau tidak, mereka akan terluka.",
  ui_story_5011_50110202_9_dialog_content = "Terluka? Maksudmu—",
  ui_story_5011_50110202_10_dialog_content = "Cordy, tarik perhatian semua Eclipsite kemari.",
  ui_story_5011_50110202_11_dialog_content = "Beri ruang untuk bertempur. Mungkin kita bisa menghabisi mereka semua sekarang.",
  ui_story_5011_50110202_12_dialog_content = "Baik, akan kuminta mereka minggir.",
  ui_story_5011_50110202_13_dialog_content = "Bagaimana caranya?",
  ui_story_5011_50110202_14_dialog_content = "Begitu rupanya. Kau belajar dengan cukup cepat.",
  ui_story_5011_50110202_15_dialog_content = "Kau benar-benar masih muda. Tak kusangka kau adalah Commander.",
  ui_story_5011_50110202_16_dialog_content = "Emmm, hanya kadang-kadang, kok.",
  ui_story_5011_50110202_17_dialog_content = "Sebaiknya kau juga mundur. Para Eclipsite itu menyerbu.",
  ui_story_5011_50110202_18_dialog_content = "Rarrrgh!",
  ui_story_5011_50110202_19_dialog_content = "Sekarang, Knight of Light!",
  ui_story_5011_50110202_20_dialog_content = "Serang!",
  ui_story_5011_50110202_21_dialog_content = "<color=#e8d9bb>DUARR!!!</color>",
  ui_story_5011_50110202_22_dialog_content = "Grrrr!",
  ui_story_5011_50110202_23_dialog_content = "Mereka kalah?!",
  ui_story_5011_50110202_24_dialog_content = "Wah, seperti dugaanku... Kau memang kuat.",
  ui_story_5011_50110202_25_dialog_content = "Ya, memang.",
  ui_story_5011_50110202_26_dialog_content = "Barusan aku melihat sesosok kesatria raksasa. Kau yang memanggilnya tadi?",
  ui_story_5011_50110202_27_dialog_content = "Maaf, aku belum bisa memberitahumu.",
  ui_story_5011_50110202_28_dialog_content = "Kesatria yang kau panggil barusan sangat luar biasa! Siapa namanya?",
  ui_story_5011_50110202_29_dialog_content = "Benarkah? Dia pendampingku, Pompey.",
  ui_story_5011_50110202_30_dialog_content = "Pendamping?",
  ui_story_5011_50110202_31_dialog_content = "Ya. Pendamping dari keyakinanku.",
  ui_story_5011_50110202_32_dialog_content = "Seorang kesatria yang terlahir untuk melindungi Lumopolis.",
  ui_story_5011_50110202_33_dialog_content = "Aku kenal seseorang bernama Charon yang memanggil kereta api sebagai pendampingnya.",
  ui_story_5011_50110202_34_dialog_content = "Kau juga begitu, ya?",
  ui_story_5011_50110202_35_dialog_content = "Tidak, ini berbeda.",
  ui_story_5011_50110202_36_dialog_content = "Pompey adalah avatar istimewa yang tercipta dari keyakinanku.",
  ui_story_5011_50110202_37_dialog_content = "Dia bukan hasil dari teknologi.",
  ui_story_5011_50110202_38_dialog_content = "Yah... Baiklah, memang tidak sama.",
  ui_story_5011_50110202_39_dialog_content = "Sepertinya kau sangat setia pada yang kau yakini. Untung tadi aku berhati-hati dengan perkataanku...",
  ui_story_5011_50110202_40_dialog_content = "Apa maksudnya?",
  ui_story_5011_50110202_41_dialog_content = "Oh, bukan apa-apa. Kenapa kau tidak menjelaskannya dari tadi?",
  ui_story_5011_50110202_42_dialog_content = "Lalu saat PlayerName memujinya, kau langsung mencerocos.",
  ui_story_5011_50110202_43_dialog_content = "Itu... Jangan hiraukan aku.",
  ui_story_5011_50110202_44_dialog_content = "Masih ada penyelidikan lain yang harus dilakukan. Ayo kita pergi.",
  ui_story_5011_50110202_45_dialog_content = "Izin melapor, Lady Hedy.",
  ui_story_5011_50110202_46_dialog_content = "Beberapa Eclipsite kabur ke desa-desa di sekitar sini. Keberadaan mereka mungkin mengancam warga.",
  ui_story_5011_50110202_47_dialog_content = "Lady Hedy, kusarankan kita segera mengejar mereka.",
  ui_story_5011_50110202_48_dialog_content = "Vice, ayo kita juga mengejar para Eclipsite itu.",
  ui_story_5011_50110202_49_dialog_content = "Kalau para penduduk sampai bertemu dengan Eclipsite, akibatnya akan sangat gawat.",
  ui_story_5011_50110202_50_dialog_content = "Baiklah!",
  ui_story_5011_50110301_1_dialog_content = "Sebentar.",
  ui_story_5011_50110301_2_dialog_content = "Prajurit, apa kau sudah berhasil memastikan di mana para Eclipsite itu berada sekarang?",
  ui_story_5011_50110301_3_dialog_content = "Kami hanya tahu bahwa mereka menuju ke timur.",
  ui_story_5011_50110301_4_dialog_content = "Kita tak tahu persis di mana keberadaan para Eclipsite itu. Kita harus memperluas pencarian.",
  ui_story_5011_50110301_5_dialog_content = "Eclipsite jadi-jadian cenderung lebih mudah mengamuk. Kalau kita mengejar, kemarahan mereka justru akan terpicu...",
  ui_story_5011_50110301_6_dialog_content = "Selain itu, kita mungkin justru akan lebih membahayakan desa-desa di sekitar sana.",
  ui_story_5011_50110301_7_dialog_content = "Kami membiarkan mereka lolos karena tidak punya rencana yang bagus.",
  ui_story_5011_50110301_8_dialog_content = "Karena itu, kusarankan kita mundur dan minta bantuan.",
  ui_story_5011_50110301_9_dialog_content = "Darkflow pada Eclipsite jadi-jadian ini sangat kuat. Jika PlayerName menggunakan kemampuan psikisnya...",
  ui_story_5011_50110301_10_dialog_content = "Baik. Biar kucoba.",
  ui_story_5011_50110301_11_dialog_content = "Grrr...",
  ui_story_5011_50110301_12_dialog_content = "Aku tahu di mana mereka. Ikuti aku.",
  ui_story_5011_50110301_13_dialog_content = "Sepertinya kau memang bisa melacak mereka.",
  ui_story_5011_50110301_14_dialog_content = "Tentu saja, aku kan Caeles...",
  ui_story_5011_50110301_15_dialog_content = "Caelestite, ras yang berbeda dengan Aurorian.",
  ui_story_5011_50110301_16_dialog_content = "Kau tak bisa menggunakan Luminatics dan tak bisa bertarung.",
  ui_story_5011_50110301_17_dialog_content = "Tapi, kau punya kemampuan psikis. Kalau itu cukup kuat, maka...",
  ui_story_5011_50110301_18_dialog_content = "Eh, kau seperti sedang membaca buku, ya?",
  ui_story_5011_50110301_19_dialog_content = "Aku pernah membaca tentang ras-mu di buku, tapi baru kali ini aku bertemu Caelestite.",
  ui_story_5011_50110301_20_dialog_content = "Wah, tak heran kau bisa memimpin prajurit Illumina.",
  ui_story_5011_50110301_21_dialog_content = "Aku hanya jadi pemimpin karena mereka memercayaiku.",
  ui_story_5011_50110301_22_dialog_content = "Maksudmu, kau bisa dipercaya?",
  ui_story_5011_50110301_23_dialog_content = "Eh, bukan begitu, aku tak bermaksud menyombong...",
  ui_story_5011_50110301_24_dialog_content = "Omong-omong, aku merasakan para Eclipsite itu tidak terlalu jauh dari sini.",
  ui_story_5011_50110301_25_dialog_content = "Mungkin bersama beberapa Aurorian juga...",
  ui_story_5011_50110301_26_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5011_50110301_27_dialog_content = "Itu suara ledakan, 'kan?",
  ui_story_5011_50110301_28_dialog_content = "Gawat...",
  ui_story_5011_50110301_29_dialog_content = "Para Aurorian itu pasti bertemu dengan Eclipsite. Kita harus pergi!",
  ui_story_5011_50110302_1_dialog_content = "Kita menghancurkan para Eclipsite itu, Joanie.",
  ui_story_5011_50110302_2_dialog_content = "Tapi, dengan bantuan Illumina dan Lumopolis, sih.",
  ui_story_5011_50110302_3_dialog_content = "Ambil mobilnya, cepat.",
  ui_story_5011_50110302_4_dialog_content = "Baiklah!",
  ui_story_5011_50110302_5_dialog_content = "Ada ribut-ribut apa sih ini?",
  ui_story_5011_50110302_6_dialog_content = "Memangnya kau mau kencan dengan Eclipsite, ya?",
  ui_story_5011_50110302_7_dialog_content = "Oh, kalian anggota Rediesel Wrench?",
  ui_story_5011_50110302_8_dialog_content = "PlayerName! Aku Joanie. Ingat aku, 'kan?",
  ui_story_5011_50110302_9_dialog_content = "Dulu aku merampok Colossus dengan Sinsa saat kita pertama kali bertemu. Ingat, 'kan?",
  ui_story_5011_50110302_10_dialog_content = "Tentu saja ingat. Kau bermaksud meledakkan Colossus milikku!",
  ui_story_5011_50110302_11_dialog_content = "Iya, sih. Tapi, bos melarang kami merampok kalian lagi.",
  ui_story_5011_50110302_12_dialog_content = "Kalian yang menciptakan ledakan itu?",
  ui_story_5011_50110302_13_dialog_content = "Iya. Mau lihat lagi dari dekat?",
  ui_story_5011_50110302_14_dialog_content = "Rediesel Wrench sering merampok karavan Lumopolis. Beberapa anggotanya ada dalam daftar buron.",
  ui_story_5011_50110302_15_dialog_content = "Demi kota itu, aku harus...",
  ui_story_5011_50110302_16_dialog_content = "Mau menangkap kami, ya? Kami punya urusan yang lebih penting daripada ditangkap, tahu.",
  ui_story_5011_50110302_17_dialog_content = "Masuklah, Joanie!",
  ui_story_5011_50110302_18_dialog_content = "Hoi, orang-orang Lumopolis. Lihat, nih! Ada ledakan spesial!",
  ui_story_5011_50110302_19_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5011_50110302_20_dialog_content = "Perlukah kita kejar mereka, Lady Hedy?",
  ui_story_5011_50110302_21_dialog_content = "Tidak.",
  ui_story_5011_50110302_22_dialog_content = "Misi kita adalah membasmi Eclipsite, lalu mengikuti petunjuk di Umbraton.",
  ui_story_5011_50110302_23_dialog_content = "Umbraton? Aku juga mau ke sana...",
  ui_story_5011_50110302_24_dialog_content = "Mau ikut? Maksudku, kau boleh ikut dengan kami.",
  ui_story_5011_50110302_25_dialog_content = "Kudengar kau diundang ke perayaan di Lumopolis. Berarti kau tamu penting di kota itu.",
  ui_story_5011_50110302_26_dialog_content = "Kami bisa mengawalmu ke Lumopolis.",
  ui_story_5011_50110302_27_dialog_content = "Misi kita belum selesai, Pittman... Sebentar, mungkin ada bagusnya juga Caelestite itu ikut.",
  ui_story_5011_50110302_28_dialog_content = "Apalagi mereka punya Colossus tua itu dan aku juga punya tugas yang harus kupantau...",
  ui_story_5011_50110302_29_dialog_content = "Sebentar, sejak kapan Colossus ada di bawah yurisdiksi Lumopolis?",
  ui_story_5011_50110302_30_dialog_content = "Tak perlu dipikirkan. Kami akan memastikan keamanan PlayerName.",
  ui_story_5011_50110302_31_dialog_content = "Selain itu, kami harus kembali ke stasiun dan berkumpul kembali, tidak mengikutimu.",
  ui_story_5011_50110302_32_dialog_content = "Mungkin prajuritku bisa menunggu kalian?",
  ui_story_5011_50110302_33_dialog_content = "Tidak perlu.",
  ui_story_5011_50110302_34_dialog_content = "Benarkah? Yah, kalau begitu, kami akan melanjutkan perjalanan. Sampai jumpa.",
  ui_story_5011_50110302_35_dialog_content = "Prajurit, kembali ke Umbraton.",
  ui_story_5011_50110401_1_dialog_content = "Bethel, kita perlu menyelidiki pemberontakan di Umbraton lagi.",
  ui_story_5011_50110401_2_dialog_content = "Kuharap kau bisa bekerja sama dengan kami sebagai perwakilan guild.",
  ui_story_5011_50110401_3_dialog_content = "Baiklah, aku sudah siap sejak mendengar kedatangan kalian.",
  ui_story_5011_50110401_4_dialog_content = "Ini hasil penyelidikan internal kami. Periksalah.",
  ui_story_5011_50110401_5_dialog_content = "Terima kasih atas kerja samamu.",
  ui_story_5011_50110401_6_dialog_content = "Sama-sama. Aku memang mau menyerahkannya kepadamu.",
  ui_story_5011_50110401_7_dialog_content = "Sudah kuduga kau akan datang lagi. Tapi, aku memang tak mengira teman sekelasku juga akan ikut.",
  ui_story_5011_50110401_8_dialog_content = "Teman sekelas?",
  ui_story_5011_50110401_9_dialog_content = "Masih ingat aku, 'kan, Hedy?",
  ui_story_5011_50110401_10_dialog_content = "Tentu. Dulu kau bersekolah di Lumopolis, Beria.",
  ui_story_5011_50110401_11_dialog_content = "Namaku Bethel, tahu! Jangan-jangan kau sengaja, ya...",
  ui_story_5011_50110401_12_dialog_content = "Ehem, bukan itu intinya. Aku kemari untuk menyelidiki pemberontakan di Umbraton.",
  ui_story_5011_50110401_13_dialog_content = "Ya, aku tahu. Pittman sudah memberitahuku.",
  ui_story_5011_50110401_14_dialog_content = "Aku... aku terlalu sibuk mengamati tempatnya sampai-sampai tidak mendengar apa yang kalian bicarakan.",
  ui_story_5011_50110401_15_dialog_content = "Biar kuperjelas, ya. Karena ini masih jam kerjaku, aku tak punya waktu untuk membicarakan masa lalu.",
  ui_story_5011_50110401_16_dialog_content = "Siapa juga yang mau? Ayolah, santai saja.",
  ui_story_5011_50110401_17_dialog_content = "Aku tak berniat berleha-leha, tahu.",
  ui_story_5011_50110401_18_dialog_content = "Baguslah.",
  ui_story_5011_50110401_19_dialog_content = "Kau masih saja angkuh seperti dulu...",
  ui_story_5011_50110401_20_dialog_content = "Bukannya tadi kau bilang tidak mau membicarakan masa lalu?",
  ui_story_5011_50110401_21_dialog_content = "Ini bukan tentang masa lalu! Aku hanya mengatakannya sambil lalu!",
  ui_story_5011_50110401_22_dialog_content = "Bethel, di berkas ini disebutkan bahwa...",
  ui_story_5011_50110401_23_dialog_content = "Ada sejumlah pemberontakan yang bersembunyi di Umbraton Timur?",
  ui_story_5011_50110401_24_dialog_content = "Benar. Kami masih menyelidikinya, tapi sayangnya kekurangan orang.",
  ui_story_5011_50110401_25_dialog_content = "Kabar tentang persembunyian mereka di utara baru saja terdengar...",
  ui_story_5011_50110401_26_dialog_content = "Di sanalah kami kehilangan jejak mereka.",
  ui_story_5011_50110401_27_dialog_content = "Apa pemberontakan yang tersisa memang sebanyak itu?",
  ui_story_5011_50110401_28_dialog_content = "Rhein, dalangnya, mengatakan bahwa masih jumlahnya lebih dari dua faksi.",
  ui_story_5011_50110401_29_dialog_content = "Ada jumlah pastinya?",
  ui_story_5011_50110401_30_dialog_content = "Aku tidak yakin.",
  ui_story_5011_50110401_31_dialog_content = "Hanya itu yang bisa kau korek setelah membawa Rhein pergi?",
  ui_story_5011_50110401_32_dialog_content = "Kalau saja kau menyerahkannya kepada kami...",
  ui_story_5011_50110401_33_dialog_content = "Lumopolis punya cara sendiri.",
  ui_story_5011_50110401_34_dialog_content = "Ayo kita kembali ke Hall of Justice dan minta bantuan. Kita perlu melakukan pencarian menyeluruh.",
  ui_story_5011_50110401_35_dialog_content = "Kalau aku tidak salah, kau akan melewati stasiun di sisi timur Umbraton dalam perjalanan kembali ke Lumopolis.",
  ui_story_5011_50110401_36_dialog_content = "Mungkin kau bisa menemukan petunjuk dalam perjalanan.",
  ui_story_5011_50110401_37_dialog_content = "Oh, PlayerName dan yang lain seharusnya sudah tiba di Umbraton.",
  ui_story_5011_50110401_38_dialog_content = "Mungkin kita bisa minta bantuan.",
  ui_story_5011_50110401_39_dialog_content = "Tapi, memangnya Caelestite itu akan datang hanya karena kau memintanya?",
  ui_story_5011_50110401_40_dialog_content = "Ini masalah Lumopolis. Kalau kau sampai melibatkan orang luar...",
  ui_story_5011_50110401_41_dialog_content = "Kalau aku minta bantuan, dia pasti datang.",
  ui_story_5011_50110401_42_dialog_content = "Begitulah PlayerName.",
  ui_story_5011_50110401_43_dialog_content = "Bagaimana kau bisa yakin?",
  ui_story_5011_50110401_44_dialog_content = "PlayerName pernah membantu Lumopolis dan dianggap sebagai teman oleh Yang Mulia Carleen.",
  ui_story_5011_50110401_45_dialog_content = "Yang Mulia juga? Oh, iya, omong-omong, aku memang pernah mendengarnya, sih.",
  ui_story_5011_50110401_46_dialog_content = "Baiklah, sebaiknya kita pergi ke stasiun. Aku yakin tak lama lagi kita akan bertemu dengan mereka.",
  ui_story_5011_50110401_47_dialog_content = "Berita hangat! Berita hangat! Lumopolis mengundang Caelestite sebagai Tamu Kehormatan!",
  ui_story_5011_50110401_48_dialog_content = "Aku mau beli satu, dong.",
  ui_story_5011_50110401_49_dialog_content = "Ini edisi spesial liburan, harganya 10 Nightium saja.",
  ui_story_5011_50110401_50_dialog_content = "Bukankah biasanya harganya juga segitu?",
  ui_story_5011_50110401_51_dialog_content = "Yang ini ada halaman tambahannya walau harganya sama. Semoga harimu indah!",
  ui_story_5011_50110401_52_dialog_content = "Wah, kau masuk di tajuk utama koran, nih, PlayerName.",
  ui_story_5011_50110401_53_dialog_content = "Apa isinya?",
  ui_story_5011_50110401_54_dialog_content = "Ehem, jangan keras-keras, ya.",
  ui_story_5011_50110401_55_dialog_content = "Katanya, \"Lumopolis Mengundang Caelestite untuk Perayaan\" dan \"Caelestite, sang Maskot\"?",
  ui_story_5011_50110401_56_dialog_content = "Maskot? Maksudnya, aku pembawa keberuntungan?",
  ui_story_5011_50110401_57_dialog_content = "Iya, semacam itu.",
  ui_story_5011_50110401_58_dialog_content = "Tapi, aku tak suka kau diberitakan seperti itu...",
  ui_story_5011_50110401_59_dialog_content = "Memangnya kenapa? Jadi pembawa keberuntungan adalah hal yang baik, 'kan?",
  ui_story_5011_50110401_60_dialog_content = "Maskot hanyalah untuk pamer. Kau bukan barang pameran.",
  ui_story_5011_50110401_61_dialog_content = "Ah, begitu rupanya.",
  ui_story_5011_50110401_62_dialog_content = "Tidak apa-apa. Aku tidak keberatan, kok. Biar saja mereka menulis sesukanya.",
  ui_story_5011_50110401_63_dialog_content = "Benar. Koran-koran di Umbraton memang selalu membesar-besarkan apa pun. Ya sudah kalau kau tidak keberatan.",
  ui_story_5011_50110401_64_dialog_content = "Sebaiknya kita pergi ke Lumopolis sesegera mungkin.",
  ui_story_5011_50110401_65_dialog_content = "Oh, aku baru saja bertanya. Katanya, semua pesawat di kota berhenti beroperasi.",
  ui_story_5011_50110401_66_dialog_content = "Yah, kita masih bisa masuk, 'kan?",
  ui_story_5011_50110401_67_dialog_content = "Iya, tapi kau harus ke <color=#FFB400>stasiun</color> di luar kota kalau mau ke Lumopolis.",
  ui_story_5011_50110401_68_dialog_content = "Stasiun?",
  ui_story_5011_50110401_69_dialog_content = "Semua kargo yang menuju ke Lumopolis harus melewati stasiun itu. Begitu juga halnya dengan yang berasal dari Illumina.",
  ui_story_5011_50110401_70_dialog_content = "Biar kutunjukkan. Aku tahu tempatnya, kok.",
  ui_story_5011_50110401_71_dialog_content = "Kau yakin? Masih ada penyelidikan yang harus kau lakukan.",
  ui_story_5011_50110401_72_dialog_content = "Aku sudah agak malu karena kau harus mengantar kami sejauh ini.",
  ui_story_5011_50110401_73_dialog_content = "Tidak apa-apa. Sebenarnya, kami juga harus mampir ke Lumopolis.",
  ui_story_5011_50110401_74_dialog_content = "Kami ingin mencari tahu apakah Hall of Justice memiliki informasi tentang pemberontakan di Umbraton.",
  ui_story_5011_50110401_75_dialog_content = "Kau menyelidikinya? Kok tadi tidak bilang saat Pittman masih ada?",
  ui_story_5011_50110401_76_dialog_content = "Kami ingin membicarakannya langsung dengan Hall, jadi tidak butuh pihak ketiga.",
  ui_story_5011_50110401_77_dialog_content = "Ayo kita pergi.",
  ui_story_5011_50110401_78_dialog_content = "Kita bertemu lagi.",
  ui_story_5011_50110401_79_dialog_content = "Halo, Hedy. Apa Pittman bersamamu?",
  ui_story_5011_50110401_80_dialog_content = "Kau berani langsung menyebut namaku padahal baru saja kenal?",
  ui_story_5011_50110401_81_dialog_content = "Memangnya aku tidak boleh memanggilmu Hedy?",
  ui_story_5011_50110401_82_dialog_content = "Baiklah... Lupakan. Panggil saja sesukamu.",
  ui_story_5011_50110401_83_dialog_content = "Pittman dan pasukannya pergi untuk mengumpulkan petunjuk.",
  ui_story_5011_50110401_84_dialog_content = "Bagaimana denganmu?",
  ui_story_5011_50110401_85_dialog_content = "Aku sedang menunggu laporan mereka.",
  ui_story_5011_50110401_86_dialog_content = "Hah? Jadi, kau menyuruh mereka bekerja sementara kau bersantai di sini?",
  ui_story_5011_50110401_87_dialog_content = "Tidak. Stasiun juga target penting. Aku baru saja menyelidikinya.",
  ui_story_5011_50110401_88_dialog_content = "Lady Hedy, kami baru saja mendapat kabar bahwa...",
  ui_story_5011_50110401_89_dialog_content = "Mereka menemukan sisa-sisa pemberontakannya?",
  ui_story_5011_50110401_90_dialog_content = "Bukan. Rediesel Wrench mendongkrak karavan guild dan membawa kabur kargonya!",
  ui_story_5011_50110401_91_dialog_content = "Salah satu dari mereka menggunakan bom... Mungkin mereka kelompok yang sebelumnya kami biarkan lolos.",
  ui_story_5011_50110401_92_dialog_content = "Tn. Pittman dan anak buahnya sedang dalam perjalanan, dan meminta bantuanmu...",
  ui_story_5011_50110401_93_dialog_content = "Dia butuh izinku, bukan bantuanku.",
  ui_story_5011_50110401_94_dialog_content = "Meski pergi sendiri, dia mengutus seseorang untuk melapor kepadaku dengan sengaja. Sangat keras kepala...",
  ui_story_5011_50110401_95_dialog_content = "Antar aku ke lokasi Pittman.",
  ui_story_5011_50110401_96_dialog_content = "Baik, Lady Hedy.",
  ui_story_5011_50110401_97_dialog_content = "Sebentar, Joanie merampok Umbraton Guild?",
  ui_story_5011_50110401_98_dialog_content = "Kau mau mengejar mereka, 'kan? Izinkan aku menemanimu. Mungkin aku bisa membujuk mereka.",
  ui_story_5011_50110401_99_dialog_content = "Kenapa kau selalu mencampuri urusan kami, orang luar?",
  ui_story_5011_50110401_100_dialog_content = "Ah... baiklah, kau boleh ikut.",
  ui_story_5011_50110401_101_dialog_content = "Lady Hedy?",
  ui_story_5011_50110401_102_dialog_content = "Caelestite Terakhir dikenal mengendarai Colossus dan punya banyak teman.",
  ui_story_5011_50110401_103_dialog_content = "Lumopolis, Illumina, Umbraton, bahkan Rediesel Wrench... Kau kenal banyak orang, 'kan?",
  ui_story_5011_50110401_104_dialog_content = "Iya. Ada yang salah?",
  ui_story_5011_50110401_105_dialog_content = "Tidak. Hanya saja aku ingat orang-orang selalu berkata, \"Caelestite itu seperti maskot.\"",
  ui_story_5011_50110401_106_dialog_content = "Mungkin kehadiranmu akan membuat keadaan lebih baik.",
  ui_story_5011_50110501_1_dialog_content = "Kami tahu ke mana orang-orang Rediesel Wrench itu pergi, Lady Hedy.",
  ui_story_5011_50110501_2_dialog_content = "Seharusnya tak lama lagi mereka akan tiba kemari.",
  ui_story_5011_50110501_3_dialog_content = "Masalah antara Umbraton Guild dan Rediesel Wrench bukan urusan kita, Pittman.",
  ui_story_5011_50110501_4_dialog_content = "Aku paham, Lady Hedy. Tapi, aku tak bisa tinggal diam kalau ada perampokan.",
  ui_story_5011_50110501_5_dialog_content = "Lagi pula, ini ada kaitannya dengan Lumopolis.",
  ui_story_5011_50110501_6_dialog_content = "Mana mungkin ada hubungannya dengan Lumopolis? Coba jelaskan.",
  ui_story_5011_50110501_7_dialog_content = "Rediesel Wrench menyergap dan merebut kargo guild, lalu melarikan diri.",
  ui_story_5011_50110501_8_dialog_content = "Barang-barang itu dibeli oleh seorang bangsawan Lumopolis di lelang bawah tanah.",
  ui_story_5011_50110501_9_dialog_content = "Guild itu tidak hanya mempekerjakan tentara bayaran, tapi juga meminta bantuan kesatria dari Lumopolis yang dipimpin oleh para bangsawan.",
  ui_story_5011_50110501_10_dialog_content = "Mereka semua mengejar Rediesel Wrench.",
  ui_story_5011_50110501_11_dialog_content = "Sepertinya, mereka tidak sempat menyembunyikan jejak karena panik.",
  ui_story_5011_50110501_12_dialog_content = "Mereka datang.",
  ui_story_5011_50110501_13_dialog_content = "Minggir, minggir. Kalau tidak, nanti kalian bakal tertabrak sampai mati!",
  ui_story_5011_50110501_14_dialog_content = "Ayo kita bicara, Joanie! Suruh anak buahmu menurunkan barang-barang itu!",
  ui_story_5011_50110501_15_dialog_content = "Lagi-lagi kamu?",
  ui_story_5011_50110501_16_dialog_content = "Maaf, karena sebelumnya kubiarkan kalian lolos, sekarang aku jadi merasa bersalah atas kejahatan lain yang kalian lakukan...",
  ui_story_5011_50110501_17_dialog_content = "Membiarkan kami lolos? Kami sendiri yang berhasil meloloskan diri!",
  ui_story_5011_50110501_18_dialog_content = "Jatuhkan senjata kalian dan angkat tangan!",
  ui_story_5011_50110501_19_dialog_content = "Dia memegang bom, <color=#FFB400>Hachi</color>. Jangan sampai dia menjatuhkannya.",
  ui_story_5011_50110501_20_dialog_content = "Apa kalian, para tentara bayaran, bekerja untuk Umbraton Guild?",
  ui_story_5011_50110501_21_dialog_content = "Kau bertanya kepadaku? Ya, benar... Sebentar, siapa kau? Aku lupa.",
  ui_story_5011_50110501_22_dialog_content = "Makin banyak saja jumlah mereka, <color=#FFB400>Gin</color>!",
  ui_story_5011_50110501_23_dialog_content = "Aku tahu. Aku tidak buta.",
  ui_story_5011_50110501_24_dialog_content = "Berpakaian putih, ya? Kalian pasti berasal dari Lumopolis.",
  ui_story_5011_50110501_25_dialog_content = "Kalian kesatria yang mau membantu kami, Nona Lumopolis?",
  ui_story_5011_50110501_26_dialog_content = "Aku bukan bagian dari para kesatria itu, tapi aku kemari untuk membantu.",
  ui_story_5011_50110501_27_dialog_content = "Kami hakim dari Lumopolis.",
  ui_story_5011_50110501_28_dialog_content = "Baiklah. Jatuhkan senjata kalian, orang-orang Rediesel! Yang lain, ambil senjata mereka!",
  ui_story_5011_50110501_29_dialog_content = "Bagaimana ini, Joanie? Kendaraan kita sudah hancur...",
  ui_story_5011_50110501_30_dialog_content = "Menyebalkan sekali.",
  ui_story_5011_50110501_31_dialog_content = "Bagaimana sekarang, Bos? Tak ada jalan keluar, nih...",
  ui_story_5011_50110501_32_dialog_content = "Ahhhhh! Menjengkelkan sekali, aku tak bisa meledakkan semuanya semauku!",
  ui_story_5011_50110501_33_dialog_content = "Tak kusangka aku harus membungkuk begini untuk berpikir...",
  ui_story_5011_50110501_34_dialog_content = "Hoi, orang-orang Lumo, berhenti ikut campur!",
  ui_story_5011_50110501_35_dialog_content = "Kami hanya mencari keadilan untuk Rediesel Wrench!",
  ui_story_5011_50110501_36_dialog_content = "Benar, benar! Salah guild sendiri, mereka menjual barang-barang kami!",
  ui_story_5011_50110501_37_dialog_content = "Kami membuat semuanya sendiri!",
  ui_story_5011_50110501_38_dialog_content = "Mereka tidak membayar kami!",
  ui_story_5011_50110501_39_dialog_content = "Dengar, 'kan? Tidak, membayar, kami!",
  ui_story_5011_50110501_40_dialog_content = "Mereka tidak membayar biaya kebohongan kami seperti yang seharusnya!",
  ui_story_5011_50110501_41_dialog_content = "Eh, biaya lisensi, Joanie...",
  ui_story_5011_50110501_42_dialog_content = "Terserah! Begini...",
  ui_story_5011_50110501_43_dialog_content = "Memangnya salah kalau kami merebut kembali barang kami?",
  ui_story_5011_50110501_44_dialog_content = "Sama, sekali, tidak!",
  ui_story_5011_50110501_45_dialog_content = "Mereka bilang guild tidak membayar, Gin.",
  ui_story_5011_50110501_46_dialog_content = "Kita tidak tahu itu benar atau salah.",
  ui_story_5011_50110501_47_dialog_content = "Tugas kita adalah melindungi barang.",
  ui_story_5011_50110501_48_dialog_content = "Kalau barangnya sampai hilang, kita yang harus ganti rugi.",
  ui_story_5011_50110501_49_dialog_content = "Lalu kita harus merebutnya kembali karena tak punya uang.",
  ui_story_5011_50110501_50_dialog_content = "Ehem, dengar, Rediesel Wrench!",
  ui_story_5011_50110501_51_dialog_content = "Turunkan senjata kalian sekarang. Kalau ingin mengajukan keluhan, harap bawa dokumen yang relevan dan diskusikan dengan guild!",
  ui_story_5011_50110501_52_dialog_content = "Mengajukan keluhan nenekmu koprol! Mana mungkin kami ada di sini kalau cara itu berhasil?!",
  ui_story_5011_50110501_53_dialog_content = "Hoi, jangan mengumpat!",
  ui_story_5011_50110501_54_dialog_content = "Oh, masih ada lagi... Akan kuledakkan kau!",
  ui_story_5011_50110501_55_dialog_content = "Karena kau ingin terlibat, Pittman, jangan diam saja kalau mereka mengajak cekcok.",
  ui_story_5011_50110501_56_dialog_content = "Tangkap mereka!",
  ui_story_5011_50110501_57_dialog_content = "Tunggu!",
  ui_story_5011_50110501_58_dialog_content = "Kau ingin membela mereka, PlayerName?",
  ui_story_5011_50110501_59_dialog_content = "Tidak, tapi...",
  ui_story_5011_50110501_60_dialog_content = "Graagh!",
  ui_story_5011_50110501_61_dialog_content = "Aku merasakan Eclipsite menuju ke sini!",
  ui_story_5011_50110502_1_dialog_content = "Graagh!",
  ui_story_5011_50110502_2_dialog_content = "Itu yang terakhir, 'kan, PlayerName?",
  ui_story_5011_50110502_3_dialog_content = "Benar. Seharusnya kita sudah aman sekarang.",
  ui_story_5011_50110502_4_dialog_content = "Kacau sekali... Kenapa Eclipsite menyerang stasiun?",
  ui_story_5011_50110502_5_dialog_content = "Dari cara gerak mereka, sepertinya mereka adalah Eclipsite jadi-jadian.",
  ui_story_5011_50110502_6_dialog_content = "Ya, mereka sama dengan Eclipsite jadi-jadian yang kita temui sebelumnya.",
  ui_story_5011_50110502_7_dialog_content = "Apa mereka itu pemberontak gerilya yang disebutkan Bethel?",
  ui_story_5011_50110502_8_dialog_content = "Aku sudah tak sanggup lagi, Joanie... Tinggalkan saja aku!",
  ui_story_5011_50110502_9_dialog_content = "Kalau tidak, tak lama lagi mereka pasti akan mengejarmu.",
  ui_story_5011_50110502_10_dialog_content = "Diam, bertahanlah!",
  ui_story_5011_50110502_11_dialog_content = "Salah, mereka sudah berhasil mengejar.",
  ui_story_5011_50110502_12_dialog_content = "Menyerahlah tanpa perlawanan!",
  ui_story_5011_50110502_13_dialog_content = "Aku ingin bicara dengan pemimpinmu!",
  ui_story_5011_50110502_14_dialog_content = "Sekarang kau baru mau bicara? Boleh juga usahamu!",
  ui_story_5011_50110502_15_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5011_50110502_16_dialog_content = "Bom?!",
  ui_story_5011_50110502_17_dialog_content = "Yang tadi itu kecil, padahal aku masih punya sekantong penuh berisi yang lebih kuat?",
  ui_story_5011_50110502_18_dialog_content = "Mau coba?",
  ui_story_5011_50110502_19_dialog_content = "Eh...",
  ui_story_5011_50110502_20_dialog_content = "Biar aku saja yang bicara denganmu.",
  ui_story_5011_50110502_21_dialog_content = "Akan kubiarkan kalian pergi asalkan kalian tinggalkan barangnya.",
  ui_story_5011_50110502_22_dialog_content = "Cepat carikan dokter untuk temanmu!",
  ui_story_5011_50110502_23_dialog_content = "Tapi, Pak...",
  ui_story_5011_50110502_24_dialog_content = "Kaudengar 'kan, Joanie? Itu tawaran terbaik yang bisa kuberikan kepadamu.",
  ui_story_5011_50110502_25_dialog_content = "Baiklah, semuanya ada di sini.",
  ui_story_5011_50110502_26_dialog_content = "Tapi, asal tahu saja, kaumku...",
  ui_story_5011_50110502_27_dialog_content = "Terluka gara-gara para prajurit Lumopolis seperti kalian dalam pertempuran!",
  ui_story_5011_50110502_28_dialog_content = "Aku tahu. Maafkan aku.",
  ui_story_5011_50110502_29_dialog_content = "Ayo kita pergi, teman-teman!",
  ui_story_5011_50110502_30_dialog_content = "Tadi kau ingin menangkap mereka, Pittman. Tapi, sekarang kau justru membiarkan mereka pergi?",
  ui_story_5011_50110502_31_dialog_content = "Lady Hedy, aku membiarkan mereka pergi setelah mengetahui duduk perkaranya.",
  ui_story_5011_50110502_32_dialog_content = "Kupikir lebih baik mereka meninggalkan barangnya dan pergi saja.",
  ui_story_5011_50110502_33_dialog_content = "Apalagi sekarang waktunya festival. Tak ada yang ingin melihat Lumopolis kacau.",
  ui_story_5011_50110502_34_dialog_content = "Sudahlah, kau memang selalu mencari alasan. Kau ingin menegakkan keadilan, tapi terlalu berbelas kasih.",
  ui_story_5011_50110502_35_dialog_content = "Lupakan saja. Aku tak akan mempermasalahkannya lagi. Aku juga tak peduli kepada mereka.",
  ui_story_5011_50110502_36_dialog_content = "Para tentara bayaran dari guild, ayo kita menginventarisasi barang.",
  ui_story_5011_50110502_37_dialog_content = "Baiklah! Terima kasih, semuanya!",
  ui_story_5011_50110502_38_dialog_content = "Semuanya lengkap.",
  ui_story_5011_50110502_39_dialog_content = "Sepertinya keributannya sudah berakhir. Kami datang tepat waktu.",
  ui_story_5011_50110502_40_dialog_content = "Kau kesatria yang diutus guild?",
  ui_story_5011_50110502_41_dialog_content = "Benar, dan ini urusan kesatria. Tolong minggir.",
  ui_story_5011_50110502_42_dialog_content = "Baru kali ini aku melihat seorang Black Knight...",
  ui_story_5011_50110502_43_dialog_content = "Apa yang kau gumamkan, Nak? Ada masalah?",
  ui_story_5011_50110502_44_dialog_content = "Kudengar ada seorang Black Knight sangat hebat yang melayani House <color=#FFB400>Hermes</color> yang terhormat.",
  ui_story_5011_50110502_44X_dialog_content = "Dia dikenal dengan nama Michelangelo.",
  ui_story_5011_50110502_45_dialog_content = "Setidaknya kau mengikuti perkembangan berita.",
  ui_story_5011_50110502_46_dialog_content = "Di mana barang-barang kami, tentara bayaran?",
  ui_story_5011_50110502_47_dialog_content = "Semuanya di sini. Silakan ambil.",
  ui_story_5011_50110502_48_dialog_content = "Barang-barang apa ini?",
  ui_story_5011_50110502_49_dialog_content = "Kenapa kau tanya?",
  ui_story_5011_50110502_50_dialog_content = "Kami harus melaporkannya setelah mengambilnya...",
  ui_story_5011_50110502_51_dialog_content = "Diamlah, aku tak punya waktu mendengar rincian pekerjaanmu.",
  ui_story_5011_50110502_52_dialog_content = "Bukankah seharusnya kau membukanya dan memeriksa apakah ada yang rusak?",
  ui_story_5011_50110502_53_dialog_content = "Tentu saja. Bukalah, tentara bayaran!",
  ui_story_5011_50110502_54_dialog_content = "Siap.",
  ui_story_5011_50110502_55_dialog_content = "Heh...",
  ui_story_5011_50110502_56_dialog_content = "Apa-apaan ini?",
  ui_story_5011_50110502_57_dialog_content = "Ini bukan barang kami!",
  ui_story_5011_50110502_58_dialog_content = "Ada apa ini?!",
  ui_story_5011_50110502_59_dialog_content = "Apa? Aku tidak tahu. Ini yang kami dapatkan dari guild...",
  ui_story_5011_50110502_60_dialog_content = "Kami hanya mengawal karavan ke Lumopolis. Kami tidak punya wewenang untuk membukanya.",
  ui_story_5011_50110502_61_dialog_content = "Ya, apalagi Rediesel menyergap kami sebelum tiba di stasiun!",
  ui_story_5011_50110502_62_dialog_content = "Jangan-jangan Rediesel Wrench sudah menukarnya?",
  ui_story_5011_50110502_63_dialog_content = "Baunya seperti bahan peledak...",
  ui_story_5011_50110502_64_dialog_content = "Kau mengenalinya, 'kan, Vida?",
  ui_story_5011_50110502_65_dialog_content = "<color=#FFB400>Bahan peledak</color>... Kotak-kotak ini penuh dengan peledak!",
  ui_story_5011_50110502_66_dialog_content = "Periksalah, Cordy.",
  ui_story_5011_50110502_67_dialog_content = "Benar, ini memang bahan peledak.",
  ui_story_5011_50110502_68_dialog_content = "Kita harus membawanya kembali untuk mengidentifikasinya, Lady Hedy.",
  ui_story_5011_50110502_69_dialog_content = "Mafia itu mencoba meledakkan dam saat terjadi pemberontakan, dan kita mendapatkan sampel bahan peledak.",
  ui_story_5011_50110502_70_dialog_content = "Kalau ini ada hubungannya...",
  ui_story_5011_50110502_71_dialog_content = "Bisa jadi semuanya memang berkaitan. Kalau begitu, aku memang harus turut menanganinya.",
  ui_story_5011_50110502_72_dialog_content = "Bawa semuanya kembali, Pittman.",
  ui_story_5011_50110502_73_dialog_content = "Semoga kau tidak menyesal karena telah membiarkan para penjahat itu lolos.",
  ui_story_5011_50110502_74_dialog_content = "Baik, Lady Hedy.",
  ui_story_5011_50110502_75_dialog_content = "Ini salah kalian, para tentara bayaran, karena tidak melindungi kargo!",
  ui_story_5011_50110502_76_dialog_content = "Aduh, kita pasti harus membayarnya dengan harga yang sangat mahal... Menangislah sepuasnya, Hachi.",
  ui_story_5011_50110502_77_dialog_content = "Chief Judge, tolong bantu kami...",
  ui_story_5011_50110502_77X_dialog_content = "Aku bukan \"Chief Judge\".",
  ui_story_5011_50110502_78_dialog_content = "Meskipun bisa membayar semua kerugian ini, aku tetap harus mengikuti prosedur.",
  ui_story_5011_50110502_79_dialog_content = "Apa maksudmu?",
  ui_story_5011_50110502_79X_dialog_content = "Pittman, kau seorang hakim—kaulah yang harus menanganinya.",
  ui_story_5011_50110502_79X1_dialog_content = "Baik, Lady Hedy.",
  ui_story_5011_50110502_80_dialog_content = "Karena sekarang ini menjadi kasus resmi, Hall of Justice akan menyita barang-barang itu.",
  ui_story_5011_50110502_81_dialog_content = "Kami akan menunjukkan hasil penemuannya pada guild.",
  ui_story_5011_50110502_82_dialog_content = "Jadi, kalian berdua tak perlu menanggung kerugiannya.",
  ui_story_5011_50110502_83_dialog_content = "Huhuhu... Ini luar biasa...",
  ui_story_5011_50110502_84_dialog_content = "Terima kasih, hakim mulia yang terhormat.",
  ui_story_5011_50110502_85_dialog_content = "Jangan berterima kasih kepadanya. Ini bagian kemampuan memaafkan yang harus dimiliki seorang hakim.",
  ui_story_5011_50110502_85X_dialog_content = "...",
  ui_story_5011_50110502_86_dialog_content = "Jadi, berterima kasihlah kepada Lumopolis, dan jangan buat dirimu tampak konyol di hadapan kami.",
  ui_story_5011_50110502_87_dialog_content = "Maaf, aku jadi terbawa suasana.",
  ui_story_5011_50110502_88_dialog_content = "Baiklah, aku tak keberatan.",
  ui_story_5011_50110502_88X_dialog_content = "Kalau begitu, tolong melaporlah kembali ke Guild secepat mungkin.",
  ui_story_5011_50110502_88X1_dialog_content = "Kalau mereka kembali dalam kondisi seperti ini, memangnya para anggota Guild akan percaya kepada mereka?",
  ui_story_5011_50110502_88X2_dialog_content = "Benar juga, sih.",
  ui_story_5011_50110502_89_dialog_content = "Tentara bayaran, aku akan menyuruh beberapa prajurit menemani kalian untuk membuktikan bahwa kalian tak bersalah.",
  ui_story_5011_50110502_90_dialog_content = "Terima kasih banyak!",
  ui_story_5011_50110502_91_dialog_content = "Mungkin perlu juga kusarankan Pittman untuk menyuruh beberapa pengawal untuk melapor kembali kepadamu, kesatria terhormat?",
  ui_story_5011_50110502_92_dialog_content = "Tidak perlu berterima kasih.",
  ui_story_5011_50110502_93_dialog_content = "Karena kasus ini sudah diambil alih oleh Hall, aku akan kembali untuk melapor.",
  ui_story_5011_50110502_94_dialog_content = "Tolong laporkan hasilnya sesegera mungkin.",
  ui_story_5011_50110502_94X_dialog_content = "Sepertinya kita harus kembali ke Lumopolis.",
  ui_story_5011_50110502_95_dialog_content = "Baik.",
  ui_story_5011_50110502_96_dialog_content = "Kami akan segera kembali ke Lumopolis dan melapor kepada Hall.",
  ui_story_5011_50110601_A1_dialog_content = "<color=#e8d9bb>Titik Pemeriksaan Lower Lumopolis</color>",
  ui_story_5011_50110601_1_dialog_content = "Tolong tunjukkan kartu identitasmu.",
  ui_story_5011_50110601_2_dialog_content = "Ini dia.",
  ui_story_5011_50110601_3_dialog_content = "Semuanya lengkap.",
  ui_story_5011_50110601_4_dialog_content = "Wah, rupanya kau Caelestite yang mereka bicarakan!",
  ui_story_5011_50110601_5_dialog_content = "Apa aku mengenalmu?",
  ui_story_5011_50110601_6_dialog_content = "Aku hanya mendengar cerita-cerita tentangmu.",
  ui_story_5011_50110601_7_dialog_content = "Oh, kusarankan kau mengunjungi pasar di sebelah barat Lower Lumopolis. Mereka menjual barang-barang bagus di sana.",
  ui_story_5011_50110601_8_dialog_content = "Jangan lupa mampir ke Lumopolis Garden juga. Ada pesta kembang api di sana.",
  ui_story_5011_50110601_9_dialog_content = "Baiklah. Terima kasih.",
  ui_story_5011_50110601_10_dialog_content = "Sama-sama. Semoga kau menikmati kota ini.",
  ui_story_5011_50110601_11_dialog_content = "Halo, Vice, PlayerName. Kukira kalian sudah sampai di sini.",
  ui_story_5011_50110601_12_dialog_content = "Sedang apa kau di sini, Carleen?",
  ui_story_5011_50110601_13_dialog_content = "Aku mendengar kabar tentang Rediesel Wrench dan bahan peledak mereka.",
  ui_story_5011_50110601_14_dialog_content = "Hall of Justice sedang mengusut kasus itu.",
  ui_story_5011_50110601_15_dialog_content = "Aku baru saja mendapat kabar bahwa Rediesel ingin balas dendam saat perayaan berlangsung.",
  ui_story_5011_50110601_16_dialog_content = "Mereka bilang begitu?",
  ui_story_5011_50110601_17_dialog_content = "Iya. Aku pernah bertemu pemimpin mereka, Sinsa, sebelumnya.",
  ui_story_5011_50110601_18_dialog_content = "Aku sudah memerintahkan penjaga untuk membuat titik pemeriksaan di Lower Lumopolis untuk mencegat mereka.",
  ui_story_5011_50110601_19_dialog_content = "Tapi, aku juga punya kabar yang lebih penting untukmu...",
  ui_story_5011_50110601_20_dialog_content = "Pittman, Hedy—pergilah ke <color=#FFB400>koloni tahanan bangsawan</color> di Lower Lumopolis secepatnya.",
  ui_story_5011_50110601_21_dialog_content = "Gereja sudah memperingatkan bahwa <color=#FFB400>Paloma Pyrrhus</color> berhasil menyelinap masuk ke kota.",
  ui_story_5011_50110601_22_dialog_content = "Apa yang dilakukan True Order di koloni tahanan?",
  ui_story_5011_50110601_23_dialog_content = "Di sanalah otak di balik insiden Umbraton ditahan... Jangan-jangan Order ingin membebaskan <color=#FFB400>Rhein</color>?",
  ui_story_5011_50110601_24_dialog_content = "Aku sudah memeriksanya. Dia tidak ada hubungannya dengan Rhein.",
  ui_story_5011_50110601_25_dialog_content = "Order selalu tertarik dengan teknologi Transformasi. Mereka juga mempelajari Eclipsite.",
  ui_story_5011_50110601_26_dialog_content = "Rhein berkaitan erat dengan \"obat penguat\" dan \"Eclipsite jadi-jadian\".",
  ui_story_5011_50110601_27_dialog_content = "Kita akan mengetahui apa yang dia inginkan setelah menemukannya. Ayo kita pergi.",
  ui_story_5011_50110601_28_dialog_content = "Baik, Yang Mulia.",
  ui_story_5011_50110601_29_dialog_content = "Aku harus berterima kasih kepada pakar penghancuran Illumina itu, Vice.",
  ui_story_5011_50110601_30_dialog_content = "Segalanya berjalan dengan sangat lancar sejak dia datang.",
  ui_story_5011_50110601_31_dialog_content = "Jika bahan peledak itu benar-benar sama dengan yang ada di Umbraton...",
  ui_story_5011_50110601_32_dialog_content = "Apa rencanamu, Carleen?",
  ui_story_5011_50110601_33_dialog_content = "Kau bermaksud menangkap para anggota Rediesel Wrench?",
  ui_story_5011_50110601_34_dialog_content = "Tidak, aku sudah mendapat titik terang...",
  ui_story_5011_50110601_35_dialog_content = "Kami mendapat hasilnya!",
  ui_story_5011_50110601_36_dialog_content = "Aku membandingkan bahan peledak yang ada di kargo dan yang didapatkan dari pemberontakan itu.",
  ui_story_5011_50110601_37_dialog_content = "Ternyata keduanya sama persis!",
  ui_story_5011_50110601_38_dialog_content = "Baiklah, sekarang kita sudah punya bukti untuk mengeluarkan surat perintah penggeledahan.",
  ui_story_5011_50110601_39_dialog_content = "Kau bermaksud...",
  ui_story_5011_50110601_40_dialog_content = "Menyelidiki Umbraton Guild.",
  ui_story_5011_50110601_41_dialog_content = "Seingatku, guild memiliki gudang untuk pengiriman reguler di Lower Lumopolis.",
  ui_story_5011_50110601_42_dialog_content = "Nah, itulah yang ingin kuselidiki. Ikutlah denganku.",
  ui_story_5011_50110601_42X_dialog_content = "<color=#e8d9bb>Di dekat Guild Warehouse</color>",
  ui_story_5011_50110601_43_dialog_content = "Cepat, cepat, cepat bongkar!",
  ui_story_5011_50110601_44_dialog_content = "Kenapa kalian sangat lamban?",
  ui_story_5011_50110601_45_dialog_content = "Kenapa harus buru-buru, sih? Ini berat, lo.",
  ui_story_5011_50110601_46_dialog_content = "Diam, teruskan saja pekerjaanmu!",
  ui_story_5011_50110601_47_dialog_content = "Kalau sampai terlambat, kalian harus membayarnya!",
  ui_story_5011_50110601_48_dialog_content = "Baiklah, baiklah. Kami akan bekerja secepat mungkin...",
  ui_story_5011_50110601_49_dialog_content = "Semunya, berhenti dan jangan bergerak!",
  ui_story_5011_50110601_50_dialog_content = "Letakkan barang yang kalian bawa. Kami akan memeriksanya.",
  ui_story_5011_50110601_51_dialog_content = "Apa maksudnya ini?",
  ui_story_5011_50110601_52_dialog_content = "Perintah dari Hall of Justice untuk menggeledah gudang.",
  ui_story_5011_50110601_53_dialog_content = "Serahkan catatan pengirimannya juga. Kami harus memeriksa segalanya.",
  ui_story_5011_50110601_54_dialog_content = "Hall ingin mengetahui segalanya?",
  ui_story_5011_50110601_55_dialog_content = "Baiklah. Tunggu sebentar. Aku akan mengambilnya.",
  ui_story_5011_50110601_56_dialog_content = "Sepertinya ada yang ganjil dengan tempat ini, Carleen...",
  ui_story_5011_50110601_57_dialog_content = "Ada apa?",
  ui_story_5011_50110601_58_dialog_content = "Ada bau menyengat yang menusuk hidungku.",
  ui_story_5011_50110601_59_dialog_content = "Mungkin itu hanya jamur. Yang seperti ini ada di semua gudang.",
  ui_story_5011_50110601_60_dialog_content = "Tidak, ini justru lebih seperti bahan peledak...",
  ui_story_5011_50110601_61_dialog_content = "Serang mereka, demi Rhein!",
  ui_story_5011_50110601_62_dialog_content = "Rrrrr!",
  ui_story_5011_50110601_63_dialog_content = "Rupanya selama ini mereka sembunyi di sini!",
  ui_story_5011_50110601_64_dialog_content = "Graaah!",
  ui_story_5011_50110602_1_dialog_content = "*Meraung*",
  ui_story_5011_50110602_2_dialog_content = "Eclipsite itu mencoba meledakkan bom! Hentikan dia!",
  ui_story_5011_50110602_3_dialog_content = "Semua sudah aman terkendali.",
  ui_story_5011_50110602_4_dialog_content = "Gah...",
  ui_story_5011_50110602_5_dialog_content = "Mungkin mereka berusaha menghancurkan barang bukti karena peristiwa di sini mulai terungkap.",
  ui_story_5011_50110602_6_dialog_content = "Jaga kargonya dan jangan biarkan siapa pun yang mencurigakan mendekat.",
  ui_story_5011_50110602_7_dialog_content = "Yang lain, habisi para Eclipsite itu!",
  ui_story_5011_50110602_8_dialog_content = "Baik, Yang Mulia!",
  ui_story_5011_50110602_9_dialog_content = "Sepertinya kita sudah memeriksa tempat yang tepat.",
  ui_story_5011_50110602_10_dialog_content = "Mereka pasti bersembunyi di guild untuk mengacaukan perayaan dan membalas dendam pada Lumopolis.",
  ui_story_5011_50110602_11_dialog_content = "Bisakah kau memeriksa area di sekitar sini, PlayerName?",
  ui_story_5011_50110602_12_dialog_content = "Mungkin ada lebih banyak Eclipsite jadi-jadian yang bersembunyi.",
  ui_story_5011_50110602_13_dialog_content = "Sepertinya tidak, tapi aku merasakan Darkflow yang tidak asing...",
  ui_story_5011_50110602_14_dialog_content = "Itu pria yang dulu muncul di Eraveil, <color=#FFB400>Mirren Gautier</color>!",
  ui_story_5011_50110602_15_dialog_content = "Apa yang dilakukan pria itu di Lumopolis?",
  ui_story_5011_50110602_16_dialog_content = "Bisa jadi ini adalah rencana Eclipsite.",
  ui_story_5011_50110602_17_dialog_content = "Dari mana asalnya, PlayerName?",
  ui_story_5011_50110602_18_dialog_content = "Sebelah sana. Ikuti aku!",
  ui_story_5011_50110602_19_dialog_content = "Kenapa Gereja bisa tahu ada utusan True Order di sini?",
  ui_story_5011_50110602_20_dialog_content = "Belum lagi lokasi pasti yang mereka sebutkan.",
  ui_story_5011_50110602_21_dialog_content = "Gereja bertindak dan memiliki jaringan mata-mata sendiri.",
  ui_story_5011_50110602_22_dialog_content = "Kalau itu sih aku tahu. Tapi, aku tidak tahu persisnya.",
  ui_story_5011_50110602_23_dialog_content = "Lady Hedy, Gereja memiliki kekuasaan lebih tinggi dari Hall of Justice.",
  ui_story_5011_50110602_24_dialog_content = "Aku tahu kita tak boleh mencampuri urusan Gereja dan harus mengikuti perintah mereka.",
  ui_story_5011_50110602_25_dialog_content = "Tapi...",
  ui_story_5011_50110602_26_dialog_content = "Kalau memang sudah tahu, kenapa kau sangat tertarik?",
  ui_story_5011_50110602_27_dialog_content = "Kurasa kita harus menyelidiki Gereja.",
  ui_story_5011_50110602_28_dialog_content = "Aku tak mau jadi orang yang hanya menerima dan mengikuti perintah.",
  ui_story_5011_50110602_29_dialog_content = "Aku ingin lebih banyak membantu Lumopolis.",
  ui_story_5011_50110602_30_dialog_content = "Menyelesaikan misi adalah bantuan terbesarmu.",
  ui_story_5011_50110602_31_dialog_content = "Tapi...",
  ui_story_5011_50110602_32_dialog_content = "Diamlah, kita sudah menemukannya...",
  ui_story_5011_50110602_33_dialog_content = "<color=#e8d9bb>Kresek, kresek.</color>",
  ui_story_5011_50110602_34_dialog_content = "Berhentilah bersembunyi. Tunjukan dirimu.",
  ui_story_5011_50110602_35_dialog_content = "Aku tahu kalian melacakku dari tadi.",
  ui_story_5011_50110602_36_dialog_content = "Gereja sudah mengawasi gerak-gerikmu sejak kau mendekati Lumopolis.",
  ui_story_5011_50110602_37_dialog_content = "Aku tahu.",
  ui_story_5011_50110602_38_dialog_content = "Tapi, kau justru memasuki kota dengan percaya diri. Para anggota Order memang tak kenal takut.",
  ui_story_5011_50110602_39_dialog_content = "Apa tujuanmu, pengkhianat?",
  ui_story_5011_50110602_40_dialog_content = "Aku melacak jejak Mirren Gautier sampai ke sini.",
  ui_story_5011_50110602_41_dialog_content = "Prioritas utamamu pastilah menyingkirkan Mirren, 'kan? Aku bisa memberimu info.",
  ui_story_5011_50110602_42_dialog_content = "Kau mau membantu kami menangkap buronan? Wah, wah, wah, sulit dipercaya.",
  ui_story_5011_50110602_43_dialog_content = "Kau sedang mengejar Mirren Gautier dan Lumopolis sekaligus, 'kan?",
  ui_story_5011_50110602_44_dialog_content = "Saat ini, prioritasku adalah Mirren, walau mungkin Lumopolis akan jadi prioritasku berikutnya.",
  ui_story_5011_50110602_45_dialog_content = "Kalau ingin bernegosiasi, sebaiknya berhentilah bersikap menjengkelkan.",
  ui_story_5011_50110602_46_dialog_content = "Baik. Dengarlah...",
  ui_story_5011_50110602_47_dialog_content = "Aku mengajakmu bicara karena pertama, aku tak ingin Gereja terlibat, dan kedua, kurasa kita bisa bekerja sama.",
  ui_story_5011_50110602_48_dialog_content = "Aku paham. Asalkan kau mau membantu kami menangkap Mirren, semua hal bisa kita negosiasikan.",
  ui_story_5011_50110602_49_dialog_content = "Kau terlalu percaya diri, ya, Pittman?",
  ui_story_5011_50110602_50_dialog_content = "Aku belum mengatakan apa pun tentang \"kolaborasi\" ini.",
  ui_story_5011_50110602_51_dialog_content = "Tolong pertimbangkan keselamatan Lumopolis, Lady Hedy.",
  ui_story_5011_50110602_52_dialog_content = "Kalau Eclipsite sampai memilih untuk menyusup saat festival diadakan, mereka pasti merencanakan sesuatu yang besar.",
  ui_story_5011_50110602_53_dialog_content = "Saat ini, tugas paling mendesak adalah menangkap Mirren.",
  ui_story_5011_50110602_54_dialog_content = "Belakangan ini orang-orang Gereja memang suka bertele-tele.",
  ui_story_5011_50110602_55_dialog_content = "Tujuan Mirren adalah menyelamatkan dalang di balik pemberontakan di Umbraton. Apa info itu cukup berharga untukmu?",
  ui_story_5011_50110602_56_dialog_content = "Baiklah, kami akan memeriksa kebenarannya.",
  ui_story_5011_50110701_1_dialog_content = "Kenapa jalannya ditutup tanpa peringatan, sih?",
  ui_story_5011_50110701_2_dialog_content = "Iya, padahal aku masih harus pergi ke Garden...",
  ui_story_5011_50110701_3_dialog_content = "Hei, prajurit. Ada apa ini?",
  ui_story_5011_50110701_4_dialog_content = "Diamlah. Tetap tenang.",
  ui_story_5011_50110701_5_dialog_content = "Silakan cari jalan memutar. Area di depan sedang ditutup.",
  ui_story_5011_50110701_6_dialog_content = "Amankan area sekitar!",
  ui_story_5011_50110701_7_dialog_content = "Hoi, kereta yang di sana, berhenti!",
  ui_story_5011_50110701_8_dialog_content = "Apa kau tak tahu siapa yang ada di dalam kereta ini? Berani-beraninya kau menyuruh kami berhenti!",
  ui_story_5011_50110701_9_dialog_content = "Tak seorang pun boleh lewat. Perintah langsung dari Hall of Justice.",
  ui_story_5011_50110701_10_dialog_content = "Sebaiknya kau sebutkan lebih spesifik supaya aku bisa meneruskan informasinya.",
  ui_story_5011_50110701_11_dialog_content = "Siapa yang ada di dalam kereta itu?",
  ui_story_5011_50110701_12_dialog_content = "Jangan lancang!",
  ui_story_5011_50110701_13_dialog_content = "Beliau adalah tamu kehormatan kota ini, <color=#FFB400>Queen Bethlehem</color> dari Northland.",
  ui_story_5011_50110701_14_dialog_content = "Tapi...",
  ui_story_5011_50110701_15_dialog_content = "Ada apa?",
  ui_story_5011_50110701_16_dialog_content = "Maafkan kami, Yang Mulia...",
  ui_story_5011_50110701_17_dialog_content = "Atmosfer kota ini agak gelisah. Apa yang terjadi?",
  ui_story_5011_50110701_18_dialog_content = "Yang Mulia Carleen memimpin pasukan untuk mencari seorang buronan kelas kakap, Yang Mulia.",
  ui_story_5011_50110701_19_dialog_content = "Carleen, katamu?",
  ui_story_5011_50110701_20_dialog_content = "Dari info terakhir yang kudapat, Mirren kabur ke arah sini, Carleen.",
  ui_story_5011_50110701_21_dialog_content = "Koloni tahanan untuk kalangan bangsawan? Di sanalah lokasi Paloma.",
  ui_story_5011_50110701_22_dialog_content = "Paloma pasti mengejar Mirren dan memaksanya menunjukkan diri.",
  ui_story_5011_50110701_23_dialog_content = "Aku ingin ambil jalan memutar dan mencegatnya, PlayerName.",
  ui_story_5011_50110701_24_dialog_content = "Serahkan saja padaku.",
  ui_story_5011_50110701_25_dialog_content = "Aku merasa ada seorang Aurorian sedang kabur di depan sana...",
  ui_story_5011_50110701_24X_dialog_content = "Ketemu. Sebenarnya ini...",
  ui_story_5011_50110701_26_dialog_content = "Rupanya kau, Caelestite! Lagi-lagi kau datang untuk mengacaukan hidupku?!",
  ui_story_5011_50110701_27_dialog_content = "Rhein? Bagaimana caramu membebaskan diri?",
  ui_story_5011_50110701_27X1_dialog_content = "Kalian kira bisa begitu saja membuangku ke koloni tahanan?",
  ui_story_5011_50110701_27X2_dialog_content = "Suatu hari nanti, akan kubalaskan dendamku kepada Lumopolis...",
  ui_story_5011_50110701_27X3_dialog_content = "Ingin tahu caraku melakukannya? Kenapa aku masih berdiri di hadapan kalian tanpa luka sedikit pun?",
  ui_story_5011_50110701_28_dialog_content = "Aku tak peduli bagaimana caramu keluar, tapi sebaiknya kau menyerah saja sekarang!",
  ui_story_5011_50110701_29_dialog_content = "Kau pasti Putri Carleen dari Lumopolis.",
  ui_story_5011_50110701_29X1_dialog_content = "Hah, aku tak mengira akan ada orang penting yang muncul.",
  ui_story_5011_50110701_30_dialog_content = "Lord Mirren sudah memberitahuku tentang dirimu.",
  ui_story_5011_50110701_31_dialog_content = "Kalau kau kusingkirkan, Lumopolis pasti akan kacau.",
  ui_story_5011_50110701_32_dialog_content = "Dan kalau berhasil, aku pasti akan dipromosikan untuk naik pangkat.",
  ui_story_5011_50110701_33_dialog_content = "Bukankah kau ini Singa Umbraton?",
  ui_story_5011_50110701_34_dialog_content = "Memangnya kau tak mau balas dendam?",
  ui_story_5011_50110701_35_dialog_content = "Telan obat penguat itu, berubahlah, dan hancurkan mereka!",
  ui_story_5011_50110701_35X1_dialog_content = "Dia mau menelan Enhancer!",
  ui_story_5011_50110701_36_dialog_content = "Aku ingin balas dendam...",
  ui_story_5011_50110701_36X2_dialog_content = "Cabik... Akan kucabik-cabik kau...",
  ui_story_5011_50110701_37_dialog_content = "<anim type=Shake><size=45>Aaaaah!</size></anim>",
  ui_story_5011_50110702_1_dialog_content = "<anim type=Shake><size=45>Rwrrr!</size></anim>",
  ui_story_5011_50110702_2_dialog_content = "Dia tak mati walau terkena pukulan itu?",
  ui_story_5011_50110702_3_dialog_content = "Dia salah satu Eclipsite yang lebih sulit dibunuh.",
  ui_story_5011_50110702_4_dialog_content = "Buat dia kewalahan, lalu tangani kudetanya.",
  ui_story_5011_50110702_4X_dialog_content = "Siap! Akan kuakhiri ini!",
  ui_story_5011_50110702_5_dialog_content = "Aku lebih khawatir tentang Mirren... Sepertinya aku berhasil menemukannya.",
  ui_story_5011_50110702_6_dialog_content = "Asalnya dari sini. Aku akan mencari tahu lokasinya, lalu kau hantam dia, Vice!",
  ui_story_5011_50110702_7_dialog_content = "Siap. Rapid Torrent!",
  ui_story_5011_50110702_8_dialog_content = "Lagi-lagi kamu?",
  ui_story_5011_50110702_9_dialog_content = "Sungguh menjengkelkan!",
  ui_story_5011_50110702_10_dialog_content = "Paloma, Caelestite... Bisa tidak sih kalian muncul satu per satu saja?",
  ui_story_5011_50110702_11_dialog_content = "Jangan-jangan kau punya radar untuk menemukanku, ya?",
  ui_story_5011_50110702_12_dialog_content = "Yah, dalam kasusku ini, aku sudah tahu tentang Eclipsium itu karena sudah bertahun-tahun mempelajarimu.",
  ui_story_5011_50110702_13_dialog_content = "Mirren Gautier, kau kemari untuk membebaskan Rhein, 'kan?",
  ui_story_5011_50110702_14_dialog_content = "Dan kurasa itu jugalah yang diinginkan si Solus yang sekarang bersembunyi di Guild itu.",
  ui_story_5011_50110702_15_dialog_content = "Maaf, tapi aku harus memberitahumu bahwa dia sudah sekarat.",
  ui_story_5011_50110702_16_dialog_content = "Maafkan aku... Lord Mirren...",
  ui_story_5011_50110702_17_dialog_content = "Kau lari? Dasar tak berguna!",
  ui_story_5011_50110702_18_dialog_content = "Bagaimana dengan anak buahmu? Kenapa mereka diam saja?",
  ui_story_5011_50110702_19_dialog_content = "Lord Rhein!",
  ui_story_5011_50110702_20_dialog_content = "Graaah!",
  ui_story_5011_50110702_21_dialog_content = "Masih ada upaya perlawanan di kota?!",
  ui_story_5011_50110702_22_dialog_content = "Sekarang, sebaiknya kaubuat aku bangga. Paham?",
  ui_story_5011_50110702_23_dialog_content = "Semua orang bodoh ini ada di sini, persis seperti yang kuinginkan...",
  ui_story_5011_50110702_24_dialog_content = "Mirren memakai Eclipsium! Dia berusaha kabur!",
  ui_story_5011_50110702_25_dialog_content = "Tidak, energi ini terasa seperti...",
  ui_story_5011_50110702_26_dialog_content = "Dia ingin membuat kita terperangkap di dimensi lain! Cepat, hentikan dia!",
  ui_story_5011_50110702_27_dialog_content = "Jangan... harap!",
  ui_story_5011_50110801_1_dialog_content = "Sial, lagi-lagi terperangkap.",
  ui_story_5011_50110801_2_dialog_content = "Jangan sampai terpisah, PlayerName.",
  ui_story_5011_50110801_2X_dialog_content = "Aku tahu.",
  ui_story_5011_50110801_3_dialog_content = "Untungnya, kita masih punya Paloma.",
  ui_story_5011_50110801_4_dialog_content = "Apa kau bisa menembusnya seperti sebelumnya, Paloma?",
  ui_story_5011_50110801_5_dialog_content = "Aku tak yakin kekuatanku masih bisa digunakan di sini.",
  ui_story_5011_50110801_6_dialog_content = "Lepaskan dan minggirlah! Kenapa kalian ada di mana-mana?!",
  ui_story_5011_50110801_7_dialog_content = "Apa yang kautunggu, Rhein?",
  ui_story_5011_50110801_8_dialog_content = "Aku... Aku...",
  ui_story_5011_50110801_9_dialog_content = "Jangan harap aku akan melepaskanmu!",
  ui_story_5011_50110801_10_dialog_content = "Mirren ingin lari, tapi Pittman...",
  ui_story_5011_50110801_11_dialog_content = "Aku harus membantu Pittman!",
  ui_story_5011_50110801_12_dialog_content = "Graaagh!",
  ui_story_5011_50110801_13_dialog_content = "Jangan menghalangiku terus, Eclipsite!",
  ui_story_5011_50110801_14_dialog_content = "Jadi, Luminatics tidak berfungsi sepenuhnya di dimensi kantong ini?",
  ui_story_5011_50110801_15_dialog_content = "Lumayan juga, tapi aku memang merasa kekuatanku tertekan.",
  ui_story_5011_50110801_16_dialog_content = "Bagaimana keadaanmu, Hedy?",
  ui_story_5011_50110801_17_dialog_content = "Jangan khawatir, Yang Mulia. Eclipsite ini muncul tepat waktu.",
  ui_story_5011_50110801_18_dialog_content = "Muncullah, Knight of Light!",
  ui_story_5011_50110801_19_dialog_content = "Apa kekuatanmu tidak terpengaruh oleh dimensi ini?",
  ui_story_5011_50110801_20_dialog_content = "Hanya terpengaruh sedikit saja.",
  ui_story_5011_50110801_21_dialog_content = "Tangkap Eclipsite itu agar kita punya peluang untuk mempelajari dimensi ini.",
  ui_story_5011_50110801_22_dialog_content = "Sebaiknya kaukerahkan seluruh kekuatanmu. Sebelumnya, dimensi ini sudah membuat kita kerepotan!",
  ui_story_5011_50110801_23_dialog_content = "Baiklah, toh bisa saja aku membelahnya jadi dua.",
  ui_story_5011_50110801_23X_dialog_content = "Lady Hedy! Aku bisa menanganinya!",
  ui_story_5011_50110801_23X1_dialog_content = "Karena kau sudah tak sabar untuk mati...",
  ui_story_5011_50110801_23X2_dialog_content = "Pittman, biarkan saja dia pergi. Tempat tertutup seperti itu akan membatasi kegesitanmu.",
  ui_story_5011_50110801_23X3_dialog_content = "Aku tak bisa menjamin bahwa pedang Pompey akan melukaimu.",
  ui_story_5011_50110801_23X4_dialog_content = "Ini bukan pertama kalinya kau harus berurusan dengan tempat sempit. Tolong, lakukan apa pun sebisamu.",
  ui_story_5011_50110801_23X5_dialog_content = "Aku paham, Lady Hedy.",
  ui_story_5011_50110801_23X6_dialog_content = "Akhirnya mau melepaskannya? Dasar sialan kau...",
  ui_story_5011_50110801_24_dialog_content = "Pompey, tebas!",
  ui_story_5011_50110801_24X1_dialog_content = "Iyuh! Untung aku berhasil bersembunyi secepat mungkin.",
  ui_story_5011_50110801_25_dialog_content = "Hei, siapa gerangan domba mungil dan naif itu?",
  ui_story_5011_50110801_26_dialog_content = "Aku terkesan dengan mainan besarmu itu.",
  ui_story_5011_50110801_27_dialog_content = "Sebaiknya aku tinggal sebentar dan bermain saja denganmu.",
  ui_story_5011_50110801_28_dialog_content = "Jangan sampai dia lolos, Pompey!",
  ui_story_5011_50110801_29_dialog_content = "Kita harus manfaatkan peluang ini untuk keluar dari sini!",
  ui_story_5011_50110801_30_dialog_content = "Carleen, tenagaku hampir habis...",
  ui_story_5011_50110801_31_dialog_content = "Ayo kita lakukan ini bersama!",
  ui_story_5011_50110801_32_dialog_content = "Awas, Vida!",
  ui_story_5011_50110801_33_dialog_content = "Aduh!",
  ui_story_5011_50110801_34_dialog_content = "Apa tak ada yang pernah mengajarimu bahwa kau tak boleh menyentuh barang milik tuan rumahmu tanpa izin?",
  ui_story_5011_50110801_35_dialog_content = "Nah, akhirnya kau keluar juga dari persembunyianmu!",
  ui_story_5011_50110801_36_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5011_50110801_37_dialog_content = "Cih, rupanya mainan besar milik domba mungil ini cukup bersemangat.",
  ui_story_5011_50110801_38_dialog_content = "Apa Lumopolis secara khusus mengutusmu untuk menyambutku?",
  ui_story_5011_50110801_39_dialog_content = "Sungguh, aku merasa tersentuh.",
  ui_story_5011_50110801_40_dialog_content = "Apa semua Eclipsite yang sudah mengalami peningkatan suka bicara melantur sepertimu?",
  ui_story_5011_50110801_41_dialog_content = "...",
  ui_story_5011_50110801_42_dialog_content = "Dengan senang hati akan kubunuh kau untuk kedua kalinya.",
  ui_story_5011_50110901_1_dialog_content = "Santai saja, dong!",
  ui_story_5011_50110901_2_dialog_content = "Itu namanya curang! Tadi aku belum siap...",
  ui_story_5011_50110901_3_dialog_content = "Tak perlu begitu, cukup julurkan saja lehermu.",
  ui_story_5011_50110901_4_dialog_content = "Pompey!",
  ui_story_5011_50110901_5_dialog_content = "Mustahil! Harusnya Luminatics-mu terkuras oleh dimensi ini...",
  ui_story_5011_50110901_6_dialog_content = "Gereja sudah lama meneliti kekuatan seperti ini.",
  ui_story_5011_50110901_7_dialog_content = "Prison Dimension, Eclipsium khusus yang melemahkan Lumina milik Aurorian.",
  ui_story_5011_50110901_7X_dialog_content = "Ini salah satu teknik Eclipsium paling rumit yang muncul dalam beberapa tahun belakangan ini.",
  ui_story_5011_50110901_8_dialog_content = "Tapi, tak ada gunanya jika berhadapan dengan Knight of Light milikku.",
  ui_story_5011_50110901_9_dialog_content = "Aduh...",
  ui_story_5011_50110901_10_dialog_content = "Uhuk!",
  ui_story_5011_50110901_11_dialog_content = "Kau tak cukup kuat untuk membantu, Paloma.",
  ui_story_5011_50110901_12_dialog_content = "Mirren adalah buruanku... Akulah yang harus menghabisinya...",
  ui_story_5011_50110901_12X1_dialog_content = "Paloma, aku sudah membaca tentang pengalamanmu dalam berkasmu...",
  ui_story_5011_50110901_12X2_dialog_content = "Kekuatan yang berasal dari kebencian dan penderitaan... tak akan membuatmu lebih kuat.",
  ui_story_5011_50110901_12X3_dialog_content = "Dan suatu saat nanti, kau akan merasakan rasa sakit dari kekuatan itu.",
  ui_story_5011_50110901_12X4_dialog_content = "Sekalian saja kaubilang... orang-orang yang tak mematuhi Lumopolis... harus mati...",
  ui_story_5011_50110901_12X5_dialog_content = "Kalau memang seperti itulah pemahamanmu tentang kata-kataku, aku tak keberatan.",
  ui_story_5011_50110901_12X6_dialog_content = "Sedikit banyak, penafsiranmu itu sebenarnya tidak jauh berbeda dari apa yang ingin kukatakan.",
  ui_story_5011_50110901_12X7_dialog_content = "Ahahaha! Paloma, kaudengar itu, tidak?",
  ui_story_5011_50110901_12X8_dialog_content = "Seberapa pun kerasnya kau berusaha menghentikanku, Lumopolis tak akan pernah memedulikanmu!",
  ui_story_5011_50110901_12X9_dialog_content = "Sekalian saja kau...",
  ui_story_5011_50110901_12X10_dialog_content = "Diam... *batuk*",
  ui_story_5011_50110901_13_dialog_content = "Lakukan saja sesukamu, asalkan kau tak menghalangiku.",
  ui_story_5011_50110901_13X1_dialog_content = "Ini medan tempurku. Durimu tak akan bisa menggoresku sedikit pun di sini!",
  ui_story_5011_50110901_13X2_dialog_content = "Argh... *batuk-batuk*",
  ui_story_5011_50110901_14_dialog_content = "Biar Hedy saja yang menangani Mirren, Paloma. Kita terus cari jalan keluar saja.",
  ui_story_5011_50110901_14X1_dialog_content = "Kalau kau terus memperpanjang masalah seperti ini, masalahnya justru akan makin bertahan lama.",
  ui_story_5011_50110901_14X2_dialog_content = "Tetaplah di belakang Pompey.",
  ui_story_5011_50110901_14X3_dialog_content = "Apa pun yang terjadi, dia memang ditakdirkan untuk mati, iya 'kan?",
  ui_story_5011_50110901_14X4_dialog_content = "Kuharap kau... bisa membuktikan kata-katamu itu...",
  ui_story_5011_50110901_14X5_dialog_content = "Paloma, kabur adalah kebiasaan buruk.",
  ui_story_5011_50110901_14X6_dialog_content = "Paloma, awas!",
  ui_story_5011_50110901_14X7_dialog_content = "<color=#e8d9bb>*pshhh!*</color>",
  ui_story_5011_50110901_14X8_dialog_content = "Mau coba-coba menyerang, ya? Sungguh menjijikkan.",
  ui_story_5011_50110901_14X9_dialog_content = "Itu akan berhasil... Paloma, ayo mundur.",
  ui_story_5011_50110901_14X10_dialog_content = "Kalau kau tetap di medan tempur, Mirren akan memanfaatkanmu untuk membatasi pilihan Hedy.",
  ui_story_5011_50110901_14X11_dialog_content = "Aku tak bisa dibatasi oleh orang dari True Order.",
  ui_story_5011_50110901_14X12_dialog_content = "Paloma, kami masih butuh kekuatanmu untuk menembus pembatasnya.",
  ui_story_5011_50110901_14X13_dialog_content = "...",
  ui_story_5011_50110901_14X14_dialog_content = "Aku tahu.",
  ui_story_5011_50110901_15_dialog_content = "Ironis, pada akhirnya tugas itu diserahkan kepada orang dari Gereja...",
  ui_story_5011_50110901_16_dialog_content = "Rhein, suruh anak buahmu menahan monster besar itu!",
  ui_story_5011_50110901_17_dialog_content = "Ya, Lord Mirren...",
  ui_story_5011_50110901_18_dialog_content = "Kamu, dasar tak berguna... Kemarilah!",
  ui_story_5011_50110901_19_dialog_content = "Aku sudah tak sanggup lagi, Lord Mirren...",
  ui_story_5011_50110901_20_dialog_content = "Kemarilah, masih ada banyak obat penguat dari arah datangnya makhluk itu!",
  ui_story_5011_50110901_21_dialog_content = "Apa yang kaulakukan?",
  ui_story_5011_50110901_22_dialog_content = "Hedy, Mirren memberikan Enhancer lagi kepada...",
  ui_story_5011_50110901_23_dialog_content = "Aduh, aduh!",
  ui_story_5011_50110901_24_dialog_content = "Argh! Tidak, tidak, kumohon, tunggu...",
  ui_story_5011_50110901_25_dialog_content = "Ha ha ha!",
  ui_story_5011_50110901_26_dialog_content = "Nikmatilah pertarungan ini, Rhein! Jangan biarkan aku bersenang-senang sendirian melawan domba sinting ini!",
  ui_story_5011_50110901_27_dialog_content = "Ini... berlebihan...",
  ui_story_5011_50110901_28_dialog_content = "Hah? Apa? Aku tak paham kata-katamu.",
  ui_story_5011_50110901_29_dialog_content = "Bukankah kau ingin jadi lebih kuat? Bukankah kau ingin melumat semua orang yang mengolok-olok dan memperalatmu?",
  ui_story_5011_50110901_30_dialog_content = "Aduh... *Tercekik*",
  ui_story_5011_50110901_31_dialog_content = "Kau sudah tak punya apa-apa lagi, Rhein, sama sepertiku. Kita ini sama saja!",
  ui_story_5011_50110901_32_dialog_content = "Telan semuanya!",
  ui_story_5011_50110901_33_dialog_content = "Aduh... Mirren, aku merasa... aku merasa...",
  ui_story_5011_50110901_34_dialog_content = "Yang kaurasakan itu adalah kekuatan murni, kekuatan murni!",
  ui_story_5011_50110901_35_dialog_content = "Baiklah, setelah kejutan tak terduga itu, ayo kita perkenalkan ulang si Singa Umbraton!",
  ui_story_5011_50110901_36_dialog_content = "Semuanya, sambutlah subjek eksperimen yang punya potensi paling besar ini!",
  ui_story_5011_50110901_37_dialog_content = "Tepuk tangan meriah untuk...",
  ui_story_5011_50110901_38_dialog_content = "Aku merasa lebih kuat... Tidak, aku... Oh, kekuatan ini!",
  ui_story_5011_50110901_39_dialog_content = "<size=45>\"Rhein & Taring dan Cakarnya yang Lebih Tajam\"!</size>",
  ui_story_5011_50110901_40_dialog_content = "<anim type=Shake><size=45>Grah!</size></anim>",
  ui_story_5011_50110902_1_dialog_content = "<anim type=Shake>Kenapa aku...</anim>",
  ui_story_5011_50110902_2_dialog_content = "Karena kau sangat ambisius dan aku menghargainya.",
  ui_story_5011_50110902_3_dialog_content = "Aku tahu apa yang kauinginkan.",
  ui_story_5011_50110902_4_dialog_content = "Bisa dibilang, Umbraton adalah pelabuhan untuk Lumopolis.",
  ui_story_5011_50110902_5_dialog_content = "Kalau kau mau, aku bisa membantumu mendapatkannya.",
  ui_story_5011_50110902_6_dialog_content = "Tapi, kau harus mencari cara untuk menggulingkan orang itu...",
  ui_story_5011_50110902_7_dialog_content = "Ya, aku akan mencari cara. Aku tak akan mengecewakanmu.",
  ui_story_5011_50110902_8_dialog_content = "Jadi, ini rencanamu?",
  ui_story_5011_50110902_9_dialog_content = "Berkeliaran di Umbraton seperti badut dan membiarkan dirimu ditangkap mata-mata Lumopolis?",
  ui_story_5011_50110902_10_dialog_content = "Huft. Aku diutus untuk menyelamatkanmu, dan bahkan tak terluka sama sekali.",
  ui_story_5011_50110902_11_dialog_content = "Seperti dirimu, aku pun merasa tersentuh.",
  ui_story_5011_50110902_12_dialog_content = "<anim type=Shake>Kalian semua... membohongiku...</anim>",
  ui_story_5011_50110902_12X_dialog_content = "Teknik transformasi Eclipsite itu jadi makin...",
  ui_story_5011_50110902_13_dialog_content = "Aduh!",
  ui_story_5011_50110902_14_dialog_content = "Kau baik-baik saja, Hedy?",
  ui_story_5011_50110902_15_dialog_content = "Awas, di belakangmu! Masih ada banyak Eclipsite di sekitar kita! Fokus!",
  ui_story_5011_50110902_16_dialog_content = "...",
  ui_story_5011_50110902_17_dialog_content = "Aku baik-baik saja. Terus tahan mereka agar tak mendekat, Pompey.",
  ui_story_5011_50110902_18_dialog_content = "<anim type=Shake>Agh... Graa... Mirren...</anim>",
  ui_story_5011_50110902_19_dialog_content = "<anim type=Shake>Kaubilang... menyelamatkanku...</anim>",
  ui_story_5011_50110902_20_dialog_content = "Jangan mendekat! Jangan sampai kau mati di sampingku, dasar tak berguna.",
  ui_story_5011_50110902_21_dialog_content = "Para petinggi menganggapmu punya banyak potensi...",
  ui_story_5011_50110902_22_dialog_content = "Buang-buang waktuku saja!",
  ui_story_5011_50110902_23_dialog_content = "Siapa petinggi yang kaumaksud itu, Mirren?",
  ui_story_5011_50110902_24_dialog_content = "Sekarang itu sudah tak penting! Orang tak berguna ini hanya jadi beban saja, dan akan kubilang seperti itu kepada mereka.",
  ui_story_5011_50110902_25_dialog_content = "Tidak bisakah kita sudahi saja perang ini? Tidakkah kau lelah menghadapinya?",
  ui_story_5011_50110902_26_dialog_content = "Perang ini sama sekali belum selesai, dasar cerewet.",
  ui_story_5011_50110902_27_dialog_content = "Selama ini kau selalu berusaha mendekatiku, Paloma. Kau lebih sopan saat masih kecil dulu.",
  ui_story_5011_50110902_28_dialog_content = "Diam!",
  ui_story_5011_50110902_29_dialog_content = "Biar aku yang menanganinya, Paloma. Pompey!",
  ui_story_5011_50110902_30_dialog_content = "Ow ow ow! Kalau berani, coba hadapi aku tanpa benda itu!",
  ui_story_5011_50110902_30X1_dialog_content = "Pompey bukan baju zirah biasa.",
  ui_story_5011_50110902_30X2_dialog_content = "Yang kaurasakan sekarang ini adalah kekuatan Luminatics murni.",
  ui_story_5011_50110902_30X3_dialog_content = "Nikmatilah rasa sakitnya... Kau pantas mendapatkannya!",
  ui_story_5011_50110902_30X4_dialog_content = "A... Arghhh!",
  ui_story_5011_50110902_31_dialog_content = "<anim type=Shake>Rhein!</anim>",
  ui_story_5011_50110902_32_dialog_content = "Awas, PlayerName!",
  ui_story_5011_50110902_33_dialog_content = "Kau baik-baik saja?",
  ui_story_5011_50110902_34_dialog_content = "Pittman, Carleen! Kalian...",
  ui_story_5011_50110902_35_dialog_content = "Kami masih bisa bertahan. Tapi, para Eclipsite itu...",
  ui_story_5011_50110902_36_dialog_content = "Ada satu yang lolos dariku!",
  ui_story_5011_50110902_37_dialog_content = "Di sini!",
  ui_story_5011_50110902_38_dialog_content = "Ya, lebih banyak... Ayo, masuk.",
  ui_story_5011_50110902_39_dialog_content = "Balaskan dendam tuanmu!",
  ui_story_5011_50111002_1_dialog_content = "<color=#e8d9bb>Buk, buk!</color>",
  ui_story_5011_50111002_2_dialog_content = "...",
  ui_story_5011_50111002_3_dialog_content = "Dasar monster, aku tak percaya ternyata kau berhasil selamat dari pedang Pompey.",
  ui_story_5011_50111002_4_dialog_content = "Aku juga merasa seperti itu, Domba Mungil.",
  ui_story_5011_50111002_5_dialog_content = "Tapi, sekarang kau hanya bertahan semata. Kau tak mau menyerang sama sekali?",
  ui_story_5011_50111002_6_dialog_content = "...",
  ui_story_5011_50111002_7_dialog_content = "Tunggu, jangan bilang kau tak punya tenaga untuk menyerang?",
  ui_story_5011_50111002_8_dialog_content = "Menjijikkan...",
  ui_story_5011_50111002_9_dialog_content = "Kau menjengkelkan sekali! Kau juga, dia juga... Kalian semua!",
  ui_story_5011_50111002_10_dialog_content = "Akan kutunjukkan, biar kalian tahu apa jadinya kalau menyepelekanku!",
  ui_story_5011_50111002_11_dialog_content = "Apa kau juga merasa bahwa udaranya jadi sangat dingin, PlayerName?",
  ui_story_5011_50111002_12_dialog_content = "Ya. Aku juga merasakan ada aliran energi yang sangat kuat!",
  ui_story_5011_50111002_13_dialog_content = "Aku punya kekuatan tersembunyi seperti ini...? Mustahil...",
  ui_story_5011_50111002_14_dialog_content = "Waow, inikah kekuatanku yang baru? Kalian semua akan...",
  ui_story_5011_50111002_15_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5011_50111002_16_dialog_content = "<size=45>Membekulah!</size>",
  ui_story_5011_50111002_17_dialog_content = "Aduh!",
  ui_story_5011_50111002_18_dialog_content = "Apa itu...?",
  ui_story_5011_50111002_19_dialog_content = "<color=#FFB400>Her Majesty Bethlehem!</color>",
  ui_story_5011_50111002_20_dialog_content = "Apa dimensinya sudah hancur?",
  ui_story_5011_50111002_21_dialog_content = "Dingin sekali... Rasanya seakan-akan semua sendiku lengket jadi satu!",
  ui_story_5011_50111002_22_dialog_content = "Mirren membeku jadi sebongkah es...",
  ui_story_5011_50111002_23_dialog_content = "Dan semua anak buah Solus juga...",
  ui_story_5011_50111002_24_dialog_content = "Kekuatan apa ini...",
  ui_story_5011_50111002_25_dialog_content = "Pompey, cegat Mirren...",
  ui_story_5011_50111002_26_dialog_content = "Berhenti.",
  ui_story_5011_50111002_27_dialog_content = "Aku yakin yang ini pasti akan berguna untukmu, Carleen.",
  ui_story_5011_50111002_28_dialog_content = "Terima kasih, Yang Mulia. Kami akan membawanya kembali untuk disidang.",
  ui_story_5011_50111002_29_dialog_content = "Anda pasti Queen Bethlehem dari Northland.",
  ui_story_5011_50111002_30_dialog_content = "Suatu kehormatan bisa bertemu dengan Anda!",
  ui_story_5011_50111002_31_dialog_content = "Ini kesatriamu?",
  ui_story_5011_50111002_32_dialog_content = "Ya. Namanya Pompey.",
  ui_story_5011_50111002_33_dialog_content = "Bagus sekali.",
  ui_story_5011_50111002_34_dialog_content = "Kau memegang jabatan yang sangat sesuai dengan keyakinan dan kebijaksanaanmu, Aurorian.",
  ui_story_5011_50111002_35_dialog_content = "Siapa namamu?",
  ui_story_5011_50111002_36_dialog_content = "Namaku Hedy Bryte, Yang Mulia. Aku bekerja di Heretics Investigation Division di Gereja.",
  ui_story_5011_50111002_37_dialog_content = "Suatu kehormatan bisa menerima pujian dari Anda.",
  ui_story_5011_50111002_38_dialog_content = "Rupanya kadang dia bisa juga bersikap rendah hati.",
  ui_story_5011_50111002_39_dialog_content = "Aku tak menyangka akan bertemu denganmu di sini, PlayerName.",
  ui_story_5011_50111002_40_dialog_content = "Anu, jadi begini, kami menemukan bahan peledak dalam kargo dari Umbraton Guild ke Lumopolis.",
  ui_story_5011_50111002_41_dialog_content = "Dalam penyelidikan, kami mendapati bahwa Mirren...",
  ui_story_5011_50111002_42_dialog_content = "Bongkahan es ini, nih!",
  ui_story_5011_50111002_43_dialog_content = "Dia berusaha kabur setelah kami melihatnya.",
  ui_story_5011_50111002_44_dialog_content = "Dan kami malah jadi terperangkap dalam dimensi kantong ini.",
  ui_story_5011_50111002_45_dialog_content = "Terima kasih, Anda sudah turun tangan tepat waktu.",
  ui_story_5011_50111002_46_dialog_content = "Aku yakin apa yang menimpa kalian ini bukanlah kebetulan.",
  ui_story_5011_50111002_47_dialog_content = "Aku khawatir ada mata-mata yang mengamati dari balik Lumopolis.",
  ui_story_5011_50111002_48_dialog_content = "Aku benar-benar minta maaf karena kalian terpaksa menghadapi ini. Kami akan sesegera mungkin mencari tahu siapa saja antek-antek mereka.",
  ui_story_5011_50111002_49_dialog_content = "Apa insiden ini sudah dilaporkan?",
  ui_story_5011_50111002_50_dialog_content = "Aku akan segera melaporkan kabar terbaru, tapi City Lord sepertinya sedang sibuk dengan urusan lain.",
  ui_story_5011_50111002_51_dialog_content = "Dia tahu apa yang dilakukannya.",
  ui_story_5011_50111002_52_dialog_content = "Ada pesan dari City Lord, Yang Mulia.",
  ui_story_5011_50111002_53_dialog_content = "Apa katanya?",
  ui_story_5011_50111002_54_dialog_content = "Dia meminta Anda untuk ke sana secepat mungkin agar tidak makin terlambat.",
  ui_story_5011_50111002_55_dialog_content = "...",
  ui_story_5011_50111002_56_dialog_content = "Sepertinya dia tak mau buang-buang waktu mengurus pemberontakan ini.",
  ui_story_5011_50111002_57_dialog_content = "Kami tak mau membuat Anda terlambat, Yang Mulia.",
  ui_story_5011_50111002_58_dialog_content = "Kata-kata saja tak akan cukup untuk mengungkapkan besarnya rasa terima kasih kami atas bantuan Anda.",
  ui_story_5011_50111002_59_dialog_content = "Dari mana kau belajar bicara seperti itu, PlayerName?",
  ui_story_5011_50111002_60_dialog_content = "Baiklah, karena memang akulah yang diundang, 'kan?",
  ui_story_5011_50111002_61_dialog_content = "Tapi, karena kalian sudah ditemani oleh Caelestite ini...",
  ui_story_5011_50111002_62_dialog_content = "Aku tak perlu mengkhawatirkan apa pun.",
  ui_story_5011_50111002_63_dialog_content = "(Itu pujian bukan, ya?)",
  ui_story_5011_50111002_64_dialog_content = "Wow...",
  ui_story_5011_50111002_65_dialog_content = "Rupanya... seperti itulah aura kemegahan Queen of the North, ya? Aku sampai-sampai tak bisa bicara.",
  ui_story_5011_50111002_66_dialog_content = "Mungkin itu karena kau membeku.",
  ui_story_5011_50111002_67_dialog_content = "...",
  ui_story_5011_50111002_68_dialog_content = "?!",
  ui_story_5011_50111002_69_dialog_content = "Kenapa, PlayerName?",
  ui_story_5011_50111002_70_dialog_content = "Dia hilang!",
  ui_story_5011_50111002_71_dialog_content = "Bongkahan es itu, Mirren...",
  ui_story_5011_50111002_72_dialog_content = "Bagaimana bisa dia hilang begitu saja?",
  ui_story_5011_50111101_A1_dialog_content = "<color=#e8d9bb>Di dalam Tempat Tinggal Lachon Hermes</color>",
  ui_story_5011_50111101_1_dialog_content = "...",
  ui_story_5011_50111101_1X1_dialog_content = "Obatku...",
  ui_story_5011_50111101_2_dialog_content = "Sudah?",
  ui_story_5011_50111101_3_dialog_content = "Hush, aku sedang bicara dengan Mirren. Biarkan aku sendiri.",
  ui_story_5011_50111101_4_dialog_content = "Uhuk! Brrr... Masih sangat dingin, sangat mengerikan...",
  ui_story_5011_50111101_5_dialog_content = "Apa kau berada di tempat yang aman?",
  ui_story_5011_50111101_6_dialog_content = "Kurasa... sepertinya begitu...",
  ui_story_5011_50111101_7_dialog_content = "Dasar pecundang.",
  ui_story_5011_50111101_8_dialog_content = "Maafkan aku karena kau terpaksa kemari untuk menyelamatkanku, Lord Figerald.",
  ui_story_5011_50111101_9_dialog_content = "Aku tak bisa terus-terusan melakukannya, jadi jangan merasa tenang dulu!",
  ui_story_5011_50111101_10_dialog_content = "Tapi, Lord Figerald, mereka masih mengejarku.",
  ui_story_5011_50111101_11_dialog_content = "Pergilah ke tempat Lachon, setidaknya kau akan aman.",
  ui_story_5011_50111101_12_dialog_content = "Tapi, lokasi Lachon mungkin saja akan ketahuan...",
  ui_story_5011_50111101_13_dialog_content = "Sejak kapan kau peduli dengan Aurorian?",
  ui_story_5011_50111101_14_dialog_content = "Siap, laksanakan!",
  ui_story_5011_50111101_14X1_dialog_content = "Kau sudah selesai bicara?",
  ui_story_5011_50111101_14X2_dialog_content = "Jangan khawatir, kau tak akan terlambat gara-gara obrolan kita.",
  ui_story_5011_50111101_14X3_dialog_content = "Kudengar kau menyebut \"Mirren\"... Apa maksudmu Mirren dari Gautier Family?",
  ui_story_5011_50111101_14X4_dialog_content = "Memangnya siapa lagi?",
  ui_story_5011_50111101_14X5_dialog_content = "Omong-omong soal itu, aku ingin berterima kasih kepadamu.",
  ui_story_5011_50111101_14X6_dialog_content = "Kalau bukan karena dirimu, aku pasti tak mungkin bisa mendapatkan anak buah yang sangat patuh seperti Mirren itu.",
  ui_story_5011_50111101_14X7_dialog_content = "Tapi, kalau soal menjalankan tugas, dia memang agak payah, sih.",
  ui_story_5011_50111101_14X8_dialog_content = "Gautier... Mirren... Dia sudah memberikan banyak referensi berharga dalam eksperimen transformasi itu.",
  ui_story_5011_50111101_14X9_dialog_content = "Tapi, hasilnya memang gagal total, sih.",
  ui_story_5011_50111101_14X10_dialog_content = "Setelah bertahun-tahun, kau masih belum juga meningkatkan transformasinya?",
  ui_story_5011_50111101_14X11_dialog_content = "Bukannya baru-baru ini kita sukses besar? Yang berdiri di rumahmu sekarang itu—Michelangelo?",
  ui_story_5011_50111101_14X12_dialog_content = "Lupakan saja Mirren. Dia tak ada artinya untukmu.",
  ui_story_5011_50111101_14X13_dialog_content = "Tapi...",
  ui_story_5011_50111101_15_dialog_content = "Kau mengirimnya berteleportasi ke mana, Figerald?",
  ui_story_5011_50111101_16_dialog_content = "Tempat paling aman untuknya, tapi bukan itu yang penting.",
  ui_story_5011_50111101_17_dialog_content = "Jangan main-main denganku, ya. Aku mau bekerja sama denganmu hanya karena kau sudah janji...",
  ui_story_5011_50111101_18_dialog_content = "Jaga bicaramu saat berhadapan dengan orang yang lebih tua, Nak.",
  ui_story_5011_50111101_19_dialog_content = "Apa-apaan kau...!",
  ui_story_5011_50111101_20_dialog_content = "Menyerahlah, Michelangelo.",
  ui_story_5011_50111101_21_dialog_content = "Pastikan anjing kampungmu itu terikat tali kekang.",
  ui_story_5011_50111101_22_dialog_content = "...",
  ui_story_5011_50111101_22X1_dialog_content = "Lachon, bukankah masalah yang kita hadapi hari ini adalah akibat kesalahanmu?",
  ui_story_5011_50111101_22X2_dialog_content = "Illumina Undercity dan Eraveil sama-sama gagal, dan kau masih saja berani bicara?",
  ui_story_5011_50111101_22X3_dialog_content = "Setidaknya mereka tak perlu lari tunggang langgang menanggung malu seperti anjing ketakutan.",
  ui_story_5011_50111101_22X4_dialog_content = "Lalu, bagaimana dengan Umbraton? Bukankah itu juga tanggung jawabmu?",
  ui_story_5011_50111101_22X5_dialog_content = "Mengerahkan Rhein saja tak cukup... Aku nyaris kehilangan Mirren!",
  ui_story_5011_50111101_22X6_dialog_content = "Enak saja—bukannya seharusnya kau mendapat ganjaran karena sudah menimbulkan semua kesulitan ini?",
  ui_story_5011_50111101_22X7_dialog_content = "Seandainya saja kau tak ceroboh saat menciptakan spesimen separuh jadi yang tak berguna itu...",
  ui_story_5011_50111101_22X8_dialog_content = "Memangnya kenapa lagi kau mencariku?",
  ui_story_5011_50111101_22X9_dialog_content = "Aku membantumu merencanakan semuanya, dari awal sampai akhir. Dari semua spesimen yang kauciptakan, hanya satu ini yang sukses besar!",
  ui_story_5011_50111101_22X10_dialog_content = "Aku selalu menjaga hati nuraniku saat bekerja dengan Eclipse.",
  ui_story_5011_50111101_22X11_dialog_content = "Tapi, apa balasan yang kauberikan kepadaku?",
  ui_story_5011_50111101_22X12_dialog_content = "Atau, kita akhiri saja hubungan kerja sama kita?",
  ui_story_5011_50111101_22X13_dialog_content = "Aku sih tak akan bilang begitu.",
  ui_story_5011_50111101_22X14_dialog_content = "Sudahlah, sekarang yang paling penting adalah obatku.",
  ui_story_5011_50111101_22X15_dialog_content = "Tanpa obat itu, aku tak akan bisa membantumu sampai bertahun-tahun.",
  ui_story_5011_50111101_23_dialog_content = "Jangan khawatir, Eclipse tak akan pernah ingkar.",
  ui_story_5011_50111101_24_dialog_content = "Akan kuberikan apa yang kauinginkan, apa pun caranya...",
  ui_story_5011_50111101_25_dialog_content = "Sebaiknya kauingat kata-katamu tadi.",
  ui_story_5011_50111101_26_dialog_content = "Bukankah harusnya kau bersiap-siap untuk menghadiri perayaan?",
  ui_story_5011_50111101_27_dialog_content = "...",
  ui_story_5011_50111101_28_dialog_content = "Tuanku.",
  ui_story_5011_50111101_29_dialog_content = "Apa Caelestite itu masih berada di lokasi pertarungan melawan Mirren?",
  ui_story_5011_50111101_30_dialog_content = "Mereka tak akan berhenti mencarinya.",
  ui_story_5011_50111101_31_dialog_content = "Ya. Mirren sedang kabur ke arah sini.",
  ui_story_5011_50111101_32_dialog_content = "Mirren memancing mereka kemari?",
  ui_story_5011_50111101_33_dialog_content = "Kita belum sepenuhnya siap.",
  ui_story_5011_50111101_34_dialog_content = "Aku tahu. Kalau berurusan dengan Eclipsite, hal seperti ini sudah biasa terjadi.",
  ui_story_5011_50111101_34X4_dialog_content = "...",
  ui_story_5011_50111101_34X5_dialog_content = "Michelangelo, kalau sampai mereka kemari, berarti giliranmu untuk unjuk gigi.",
  ui_story_5011_50111101_35_dialog_content = "Aku tahu apa yang harus kita lakukan.",
  ui_story_5011_50111101_36_dialog_content = "Kaulah yang paling kupercaya.",
  ui_story_5011_50111101_37_dialog_content = "Jangan sampai kita ketahuan, Michelangelo.",
  ui_story_5011_50111101_38_dialog_content = "Figerald sudah menjelaskan ketentuannya, dan salah satunya adalah melindungi Mirren.",
  ui_story_5011_50111101_39_dialog_content = "Kalau kita berhasil, aku akan berumur panjang...",
  ui_story_5011_50111101_40_dialog_content = "Dan kau akan bisa terus menikmati segala yang kaumiliki di bawah perlindunganku.",
  ui_story_5011_50111201_1_dialog_content = "Lewat sini!",
  ui_story_5011_50111201_2_dialog_content = "Kau yakin, PlayerName? Mirren menghilang tanpa jejak...",
  ui_story_5011_50111201_3_dialog_content = "Aku bisa merasakannya! Tapi, aku tak tahu bagaimana cara menjelaskannya kepadamu...",
  ui_story_5011_50111201_4_dialog_content = "Darkflow ini sangat aneh, tidak seperti yang pernah kurasakan sebelumnya, tapi...",
  ui_story_5011_50111201_5_dialog_content = "Aku tahu di mana lokasinya.",
  ui_story_5011_50111201_6_dialog_content = "Baiklah, aku paham. Aku akan mengikutimu.",
  ui_story_5011_50111201_7_dialog_content = "Kau paham?",
  ui_story_5011_50111201_8_dialog_content = "Tidak, tidak terlalu, tapi aku tetap akan mengikutimu.",
  ui_story_5011_50111201_9_dialog_content = "Sepertinya si Hedy ini sangat percaya kepada PlayerName.",
  ui_story_5011_50111201_10_dialog_content = "Tidak, aku masih ragu. Lagi pula, sekarang kita menuju pusat Lumopolis Garden.",
  ui_story_5011_50111201_11_dialog_content = "Kalau Mirren memang kabur ke arah sini, berarti Pompey berhasil mengacaukan pikirannya, atau...",
  ui_story_5011_50111201_12_dialog_content = "Ada seseorang yang menunggu untuk memberinya tempat tinggal.",
  ui_story_5011_50111201_13_dialog_content = "Para bangsawan tinggal di sini, jadi apa maksudmu...",
  ui_story_5011_50111201_14_dialog_content = "Itu bukan hal aneh. Ini kan Lumopolis.",
  ui_story_5011_50111201_15_dialog_content = "Berhenti.",
  ui_story_5011_50111201_16_dialog_content = "Itu si Black Knight!",
  ui_story_5011_50111201_17_dialog_content = "Kalian memasuki area milik pribadi. Berbaliklah.",
  ui_story_5011_50111201_18_dialog_content = "Biar kuperkenalkan diriku lagi, Michelangelo. Aku Hedy dari Heretics Investigation Division.",
  ui_story_5011_50111201_19_dialog_content = "Semua orang yang tahu tentang Gereja pasti paham artinya.",
  ui_story_5011_50111201_20_dialog_content = "Di sebelahku ini Kapten Carleen, putri City Lord.",
  ui_story_5011_50111201_21_dialog_content = "Kami akan masuk untuk menyelidiki...",
  ui_story_5011_50111201_22_dialog_content = "Berbalik.",
  ui_story_5011_50111201_23_dialog_content = "Siapa pun yang kaucari, dia tak ada di sini.",
  ui_story_5011_50111201_24_dialog_content = "Bagaimana kau bisa tahu bahwa kami sedang mengejar seseorang?",
  ui_story_5011_50111201_25_dialog_content = "Berita menyebar dengan cepat di Lumopolis, dan kalian juga menimbulkan keributan cukup besar di Lower Lumopolis.",
  ui_story_5011_50111201_26_dialog_content = "Apa pun yang kaucari, dia tak ada di sini.",
  ui_story_5011_50111201_27_dialog_content = "Bagaimana kau tahu?",
  ui_story_5011_50111201_28_dialog_content = "Karena aku ada di sini.",
  ui_story_5011_50111201_29_dialog_content = "Tolong, jangan ikut campur. Aku punya wewenang saat Lumopolis sedang terancam...",
  ui_story_5011_50111201_30_dialog_content = "Terancam? Oleh apa?",
  ui_story_5011_50111201_31_dialog_content = "Yang kulihat adalah bahwa kau menyalahgunakan kekuasaanmu dengan dalih melakukan penyelidikan.",
  ui_story_5011_50111201_32_dialog_content = "Apa-apaan kau...",
  ui_story_5011_50111201_33_dialog_content = "Ini masa festival, dan aku tak akan membiarkanmu merusak keluhuran nama baik para bangsawan.",
  ui_story_5011_50111201_34_dialog_content = "Kalian semua, silakan pergi.",
  ui_story_5011_50111201_35_dialog_content = "PlayerName...",
  ui_story_5011_50111201_36_dialog_content = "Baiklah, arahnya masih ke sini.",
  ui_story_5011_50111201_37_dialog_content = "Persis melewati tempatnya berdiri!",
  ui_story_5011_50111201_38_dialog_content = "...",
  ui_story_5011_50111201_39_dialog_content = "Minggir, Michelangelo. Kau tak punya hak untuk menghentikan kami!",
  ui_story_5011_50111201_40_dialog_content = "Aku tidak bisa melakukannya.",
  ui_story_5011_50111201_41_dialog_content = "Hunus pedangmu, Pompey...",
  ui_story_5011_50111201_42_dialog_content = "Kau memanggilnya di sini?",
  ui_story_5011_50111201_43_dialog_content = "Kenapa tidak? Dia kan menyembunyikan Eclipsite dan menghalangi keadilan!",
  ui_story_5011_50111201_44_dialog_content = "Mungkin kau memang diperintahkan untuk menghentikan kami, Michelangelo.",
  ui_story_5011_50111201_45_dialog_content = "Tapi, kau pasti kalah karena kau bukan tandingan kami.",
  ui_story_5011_50111201_45X1_dialog_content = "Knight of Light. Lanjutkan.",
  ui_story_5011_50111201_45X2_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5011_50111201_45X3_dialog_content = "Kau yakin mau berdiri di tengah jalan?",
  ui_story_5011_50111201_45X4_dialog_content = "Apa yang akan kaupakai untuk melawan pedang Pompey? Keahlian pedangmu yang luar biasa?",
  ui_story_5011_50111201_45X5_dialog_content = "Omong-omong, aku akan tetap di sini saja.",
  ui_story_5011_50111201_45X6_dialog_content = "Kalau begitu, PlayerName, kauteruskan saja. Dengan Pompey di sisimu, dia tak akan mampu menghentikanmu.",
  ui_story_5011_50111201_45X7_dialog_content = "PlayerName, ayo terus bergerak.",
  ui_story_5011_50111201_45X8_dialog_content = "Yang Mulia Carleen, maafkan aku...",
  ui_story_5011_50111201_45X9_dialog_content = "<color=#e8d9bb>*pshhh!*</color>",
  ui_story_5011_50111201_45X10_dialog_content = "Hmm...",
  ui_story_5011_50111201_45X11_dialog_content = "Pedang Pompey tak cukup kuat untuk menghentikannya.",
  ui_story_5011_50111201_45X12_dialog_content = "Kalian semua—keluar dari sini.",
  ui_story_5011_50111201_46_dialog_content = "Kalau kalian ingin bertarung, aku tak akan ke mana-mana.",
  ui_story_5011_50111201_47_dialog_content = "Yang bisa kulakukan hanyalah mengulur waktu...",
  ui_story_5011_50111201_48_dialog_content = "Tadi kaubilang...",
  ui_story_5011_50111201_49_dialog_content = "Ini saatnya untukku.",
  ui_story_5011_50111201_49X1_dialog_content = "Aku gagal memenuhi harapanmu, tapi aku harus mengungkapkannya...",
  ui_story_5011_50111201_49X2_dialog_content = "Aku melakukannya agar kau bisa lebih memahami situasi dan punya lebih banyak waktu untuk menyiapkan langkah penanggulangan yang layak...",
  ui_story_5011_50111201_50_dialog_content = "Semoga kau bisa pergi dengan selamat.",
  ui_story_5011_50111201_50X1_dialog_content = "Kalau ada kesempatan, aku pasti akan membalas kebaikanmu.",
  ui_story_5011_50111201_51_dialog_content = "Dia bergumam apa, sih?",
  ui_story_5011_50111201_52_dialog_content = "<anim type=Shake>Ini saatnya untukku...</anim>",
  ui_story_5011_50111201_53_dialog_content = "Ta-tanahnya berguncang... Apa yang dilakukannya!?",
  ui_story_5011_50111201_54_dialog_content = "Aku tak melihat dia meminum apa pun! Tapi, wujudnya...",
  ui_story_5011_50111201_55_dialog_content = "<anim type=Shake>Kekuatan... Kekuatan lebih besar...!!!</anim>",
  ui_story_5011_50111201_56_dialog_content = "Mundur! Minggir! Ada yang tidak beres dengannya!",
  ui_story_5011_50111201_57_dialog_content = "Dia... bertambah tinggi!? Bagaimana mungkin...? Apa aku berhalusinasi!?",
  ui_story_5011_50111201_57X1_dialog_content = "Dia... Eclipsite jadi-jadian...?",
  ui_story_5011_50111201_58_dialog_content = "<anim type=Shake>Ya, beginilah rasanya... Kekuatan murni tak tertandingi...!</anim>",
  ui_story_5011_50111201_59_dialog_content = "<anim type=Shake><size=45>Apa waktuku... akhirnya tiba!?</size></anim>",
  ui_story_5011_50111201_60_dialog_content = "Dia menjadi sangat, sangat... besar!!!",
  ui_story_5011_50111201_61_dialog_content = "Sepuluh meter!? Tidak, lebih seperti...",
  ui_story_5011_50111201_62_dialog_content = "Fokuskan bidikanmu! Rapid Torrent!",
  ui_story_5011_50111201_63_dialog_content = "Terimalah hukumanmu!",
  ui_story_5011_50111201_64_dialog_content = "<anim type=Shake><size=45>Aarrrrrrrrgh!</size></anim>",
  ui_story_5011_50111201_65_dialog_content = "Tidak berpengaruh!?",
  ui_story_5011_50111201_65X1_dialog_content = "Dalam wujudnya sekarang, seluruh tubuhnya diselubungi Darkflow. Luminatics biasa tak akan berpengaruh terhadapnya...",
  ui_story_5011_50111201_65X2_dialog_content = "Kecuali...",
  ui_story_5011_50111201_66_dialog_content = "Awas!",
  ui_story_5011_50111201_67_dialog_content = "<color=#e8d9bb>*brak! klang!*</color>",
  ui_story_5011_50111201_68_dialog_content = "Kekuatan mengerikan ini...!?",
  ui_story_5011_50111201_69_dialog_content = "Biar aku saja! Pompey!",
  ui_story_5011_50111201_69X1_dialog_content = "Kecuali kita menggunakan senjata besar yang terhubung ke Luminatics!",
  ui_story_5011_50111201_69X2_dialog_content = "Dan Pompey punya alat yang tepat untuk itu!",
  ui_story_5011_50111201_70_dialog_content = "Lindungi semua orang!",
  ui_story_5011_50111201_71_dialog_content = "Gah, gah!!!",
  ui_story_5011_50111201_72_dialog_content = "Eclipsite-nya banyak sekali! Dari mana datangnya mereka!?",
  ui_story_5011_50111201_73_dialog_content = "<color=#e8d9bb>*duar! brak!*</color>",
  ui_story_5011_50111201_74_dialog_content = "<anim type=Shake><size=45>Aarrrrrrrrgh...!?</size></anim>",
  ui_story_5011_50111201_75_dialog_content = "Pompey! Satu hantaman lagi!",
  ui_story_5011_50111201_76_dialog_content = "Pertarungan kekuatan besar... Kita tak bisa ikut campur dalam pertarungan semacam ini...",
  ui_story_5011_50111201_77_dialog_content = "PlayerName, ayo tangani para Eclipsite yang tersebar itu!",
  ui_story_5011_50111201_78_dialog_content = "Graaaah...!",
  ui_story_5011_50111201_79_dialog_content = "Baiklah. Siap.",
  ui_story_5011_50111201_80_dialog_content = "Hedy, kuserahkan yang satu ini kepadamu!",
  ui_story_5011_50111201_81_dialog_content = "Aku yakin aku orang yang bisa dipercaya...",
  ui_story_5011_50111201_82_dialog_content = "Kau bisa mengandalkanku!",
  ui_story_5011_50111301_1_dialog_content = "Lihat, kesatria besar itu apa!?",
  ui_story_5011_50111301_2_dialog_content = "Lari, lari... lari!",
  ui_story_5011_50111301_3_dialog_content = "Semuanya! Lewat sini! Ja-Jangan panik...!",
  ui_story_5011_50111301_4_dialog_content = "Hedy! Setelah selesai mengatasi para Eclipsite itu, kita...",
  ui_story_5011_50111301_5_dialog_content = "Menjauhlah dariku! Menjauhlah dari Pompey dan Eclipsite raksasa ini—",
  ui_story_5011_50111301_6_dialog_content = "<anim type=Shake><size=45>Raarrrrrrrrgh!</size></anim>",
  ui_story_5011_50111301_7_dialog_content = "Monster!",
  ui_story_5011_50111301_8_dialog_content = "Baiklah! Carleen, Vice, kita...",
  ui_story_5011_50111301_9_dialog_content = "Tunggu! Mana Paloma!?",
  ui_story_5011_50111301_10_dialog_content = "Apa ada yang lihat Paloma?",
  ui_story_5011_50111301_11_dialog_content = "Jangan-jangan, dia terus mengejar Mirren...?",
  ui_story_5011_50111301_12_dialog_content = "<anim type=Shake><size=45>Graooo!</size></anim>",
  ui_story_5011_50111301_13_dialog_content = "Waspada, reruntuhannya berjatuhan!",
  ui_story_5011_50111301_14_dialog_content = "Ayo, ini saatnya! Hancurkan dia, Pompey!",
  ui_story_5011_50111301_15_dialog_content = "Ayo kita pergi! Jangan sampai Mirren lolos!",
  ui_story_5011_50111301_16_dialog_content = "Michelangelo, Lumopolis bukan taman bermainmu!",
  ui_story_5011_50111301_17_dialog_content = "Tunggu *batuk*! Asap ini... Aku tak bisa lihat apa-apa—",
  ui_story_5011_50111301_18_dialog_content = "... Apa ini... <color=#FFB400>kristal salju</color>?",
  ui_story_5011_50111301_19_dialog_content = "Aku... Akhirnya aku...!",
  ui_story_5011_50111301_20_dialog_content = "Lihat wajahmu yang menjijikkan itu, Mirren.",
  ui_story_5011_50111301_21_dialog_content = "...",
  ui_story_5011_50111301_22_dialog_content = "Rencananya tak bisa mengimbangi perubahan ini. Aku harus melakukan penyesuaian.",
  ui_story_5011_50111301_23_dialog_content = "Tapi, reaksimu juga sangat cepat, dasar anjing kampung... Aku tak menyangka ternyata kau punya kekuatan seperti itu...",
  ui_story_5011_50111301_23X1_dialog_content = "Jelas bahwa kau sudah merawatnya dengan baik selama bertahun-tahun ini.",
  ui_story_5011_50111301_23X2_dialog_content = "Apa situasi di luar sana separah itu?",
  ui_story_5011_50111301_23X3_dialog_content = "Bocah itu harus bertransformasi agar bisa mengakhiri ini, tapi...",
  ui_story_5011_50111301_24_dialog_content = "Cepat atau lambat, harus ada pengorbanan, Figerald. Entah aku atau kau...",
  ui_story_5011_50111301_25_dialog_content = "Usiamu belum seratus tahun, dan hidupmu bahkan sudah lebih mapan daripada aku.",
  ui_story_5011_50111301_26_dialog_content = "Pak, apa yang harus kita lakukan berikutnya?",
  ui_story_5011_50111301_27_dialog_content = "Berikutnya? Kau tak mau mengorbankan pengikutmu, dan sekarang kau malah menanyakan langkah berikutnya kepadaku?",
  ui_story_5011_50111301_28_dialog_content = "Keluarlah, gadis kecil.",
  ui_story_5011_50111301_29_dialog_content = "...",
  ui_story_5011_50111301_30_dialog_content = "Paloma? Kau masih mengejarku!?",
  ui_story_5011_50111301_31_dialog_content = "Mirren, urusan kita belum selesai.",
  ui_story_5011_50111301_32_dialog_content = "Menurutmu apa yang kaulakukan, datang kemari sendirian?",
  ui_story_5011_50111301_33_dialog_content = "Menurutku? Kau mau mendengarnya lagi?",
  ui_story_5011_50111301_34_dialog_content = "Atau, apa sebaiknya aku bicara mewakilinya saja?",
  ui_story_5011_50111301_35_dialog_content = "Kau!",
  ui_story_5011_50111301_36_dialog_content = "Hmph.",
  ui_story_5011_50111301_37_dialog_content = "Pa... Paloma, lain kali jangan pergi secepat itu...",
  ui_story_5011_50111301_38_dialog_content = "Teman-temanmu tak akan bisa menyusulmu.",
  ui_story_5011_50111301_39_dialog_content = "Kamu...",
  ui_story_5011_50111301_40_dialog_content = "Dukamu di masa lalu tak ada apa-apanya dibandingkan duka kami!",
  ui_story_5011_50111301_41_dialog_content = "Kau sendirian!? Hanya karena monster beku itu tak ada di sini, kaukira...",
  ui_story_5011_50111301_42_dialog_content = "... Kristal salju?",
  ui_story_5011_50111301_43_dialog_content = "Sesukamu.",
  ui_story_5011_50111301_44_dialog_content = "<size=45>Argh!? Ah!!!</size>",
  ui_story_5011_50111301_45_dialog_content = "Kau!? Dia!... Itu... Itu dia!!!",
  ui_story_5011_50111301_46_dialog_content = "... Bethlehem. Queen of the North.",
  ui_story_5011_50111301_47_dialog_content = "Terima kasih atas perkenalannya, tapi sayangnya, aku tak tahu namamu.",
  ui_story_5011_50111301_48_dialog_content = "Sama-sama. Namaku Figerald. Apa pendapat Yang Mulia tentang nama ini?",
  ui_story_5011_50111301_49_dialog_content = "Nama ini...!?",
  ui_story_5011_50111301_50_dialog_content = "Ratu nan cantik, bisa tolong... jangan ikut campur?",
  ui_story_5011_50111301_51_dialog_content = "Kau berdiri di tanah kaum Aurorian. Bagaimana menurutmu?",
  ui_story_5011_50111301_52_dialog_content = "Ck, ck, ck, ck, ck... Aku tak suka perasaan seperti ini.",
  ui_story_5011_50111301_53_dialog_content = "Mirren, akan kuberi kau satu kesempatan terakhir. Tangani makhluk-makhluk lemah di sana itu.",
  ui_story_5011_50111301_54_dialog_content = "Soal Yang Mulia, dengan senang hati aku akan menghiburnya.",
  ui_story_5011_50111301_55_dialog_content = "Aku bisa melakukannya! Selama gadis aneh itu tidak dekat-dekat denganku!",
  ui_story_5011_50111301_56_dialog_content = "Akan kutangani begundal ini, makhluk menjijikkan ini, makhluk tak berguna ini...",
  ui_story_5011_50111301_57_dialog_content = "<size=45>Akan kubunuh mereka semua!!!</size>",
  ui_story_5011_50111302_1_dialog_content = "Suara apa itu?",
  ui_story_5011_50111302_2_dialog_content = "Hedy, ada apa?",
  ui_story_5011_50111302_3_dialog_content = "Kak, kesatria dalam buku ini... pada akhirnya mati.",
  ui_story_5011_50111302_4_dialog_content = "Kau masih ingin membaca di sini padahal hari ini ada perayaan?",
  ui_story_5011_50111302_5_dialog_content = "Aku ingin mengajak Pompey jalan-jalan, tapi hari ini jalanan dipenuhi banyak orang.",
  ui_story_5011_50111302_6_dialog_content = "Pompey?",
  ui_story_5011_50111302_7_dialog_content = "Oh, dia teman baruku.",
  ui_story_5011_50111302_8_dialog_content = "Apa kau ingat mimpi yang dulu biasa muncul dalam tidurku? Mimpi aku dikejar-kejar Eclipsite?",
  ui_story_5011_50111302_9_dialog_content = "Nah, aku mulai bermimpi ada kesatria yang muncul dan menyelamatkanku dengan pedangnya yang hebat.",
  ui_story_5011_50111302_10_dialog_content = "Saat aku menceritakannya kepada ayahku, dia mengajakku ke ruang bawah tanah dan menunjukkan baju zirah yang sangat besar...",
  ui_story_5011_50111302_11_dialog_content = "Baju zirah milik leluhur keluargamu yang tersohor, Knight of Light itu?",
  ui_story_5011_50111302_12_dialog_content = "Oh, jadi kau juga sudah pernah mendengar tentangnya?",
  ui_story_5011_50111302_13_dialog_content = "Dia adalah kesatria yang muncul dalam mimpiku dan menyelamatkanku.",
  ui_story_5011_50111302_14_dialog_content = "Aku... aku membangunkan baju zirah itu dengan Luminatics dan menamainya Pompey.",
  ui_story_5011_50111302_15_dialog_content = "Dia luar biasa, dan dia bisa melakukan apa saja untukku... Tapi, dia memang sering memecahkan cangkir teh dan alat makan, sih.",
  ui_story_5011_50111302_16_dialog_content = "Kadang aku mengajaknya berjalan-jalan, tapi kebanyakan orang langsung bersembunyi saat melihat Pompey...",
  ui_story_5011_50111302_17_dialog_content = "Jadi, aku hanya bisa mengajaknya jalan-jalan keluar saat tak ada orang di sekitar.",
  ui_story_5011_50111302_18_dialog_content = "Oh...",
  ui_story_5011_50111302_19_dialog_content = "Apa kau marah? Apa aku dan Pompey berbuat salah?",
  ui_story_5011_50111302_20_dialog_content = "Tidak, Hedy... Pompey adalah karunia dari Dewa.",
  ui_story_5011_50111302_21_dialog_content = "Karena hatimu suci, Dewa pun menuntun Pompey kepadamu.",
  ui_story_5011_50111302_22_dialog_content = "Melangkahlah di jalan yang benar bersamanya, sampai kau berhasil melalui sekian banyak ujian dari God of Light.",
  ui_story_5011_50111302_23_dialog_content = "Jalan yang benar...",
  ui_story_5011_50111302_24_dialog_content = "<anim type=Shake><size=45>Rwrrr!</size></anim>",
  ui_story_5011_50111302_25_dialog_content = "<color=#e8d9bb>*brak-brak!*</color>",
  ui_story_5011_50111302_26_dialog_content = "Cepat! Lihat! Makhluk itu... Dia bangun lagi!",
  ui_story_5011_50111302_27_dialog_content = "Bagaimana kita bisa... jatuh ke sini...?",
  ui_story_5011_50111302_28_dialog_content = "Kau! Kaulah yang seharusnya menunduk di hadapan White Night!",
  ui_story_5011_50111302_29_dialog_content = "<anim type=Shake><size=45>Groaaaaar!</size></anim>",
  ui_story_5011_50111302_30_dialog_content = "Te-teman-temanku akan menghentikanmu...",
  ui_story_5011_50111302_31_dialog_content = "Pompey... Ayo hantam kepalanya—",
  ui_story_5011_50111302_32_dialog_content = "Hantam! Sekarang!",
  ui_story_5011_50111302_33_dialog_content = "<color=#e8d9bb>*klang!*</color>",
  ui_story_5011_50111302_34_dialog_content = "<anim type=Shake>Ba... Bagaimana...?</anim>",
  ui_story_5011_50111302_35_dialog_content = "<anim type=Shake>Figer...ald...</anim>",
  ui_story_5011_50111302_36_dialog_content = "Percuma.",
  ui_story_5011_50111302_37_dialog_content = "Apa pangkatmu di antara Eclipse?",
  ui_story_5011_50111302_38_dialog_content = "Aku? Ck, ck... Kau akan punya banyak waktu untuk mengenalku lebih dalam.",
  ui_story_5011_50111302_39_dialog_content = "Karena sekarang sudah selesai, aku punya hadiah untukmu... Lachon!",
  ui_story_5011_50111302_40_dialog_content = "Apa yang akan kaulakukan sekarang?",
  ui_story_5011_50111302_41_dialog_content = "Aku hanya ingin bilang...",
  ui_story_5011_50111302_42_dialog_content = "Kerusuhan di luar sana sepertinya sudah mereda.",
  ui_story_5011_50111302_43_dialog_content = "...",
  ui_story_5011_50111302_44_dialog_content = "Michelangelo sudah berhasil menuntaskan tugasnya.",
  ui_story_5011_50111302_45_dialog_content = "Ayo manfaatkan peluang ini untuk keluar dari sini...",
  ui_story_5011_50111302_46_dialog_content = "Lachon, Lachon, Lachon... Kau begitu tak sabar ingin kabur, ya?",
  ui_story_5011_50111302_47_dialog_content = "Tidak, masih ada misi yang harus kautuntaskan—",
  ui_story_5011_50111302_48_dialog_content = "Misalnya, kau masih harus menceritakan kisahmu kepada orang-orang ini.",
  ui_story_5011_50111302_49_dialog_content = "...",
  ui_story_5011_50111302_50_dialog_content = "Kalau kau sedang tak ingin menceritakannya, biar aku saja.",
  ui_story_5011_50111302_51_dialog_content = "Biar kuberi tahu mereka tentang bagaimana kau gagal menjadi City Lord dan jadi membenci Schwartz karenanya.",
  ui_story_5011_50111302_52_dialog_content = "Atau bahwa kau sudah mengorbankan segalanya demi Lumopolis, tapi tetap saja kau tak menerima secuil pun penghargaan yang mestinya kaudapatkan.",
  ui_story_5011_50111302_53_dialog_content = "Dan, tentu saja, mereka juga harus tahu bahwa sekarang, saat hidupmu sudah hampir berakhir, napasmu sudah hampir habis... tapi kau masih berharap bisa hidup—",
  ui_story_5011_50111302_54_dialog_content = "Bisa terus hidup dan mempertahankan tubuh ringkih terakhir...",
  ui_story_5011_50111302_55_dialog_content = "Dari keluarga Hermes ini.",
  ui_story_5011_50111302_55X1_dialog_content = "Begitulah, dia melakukan segala cara semampunya untuk memengaruhi lebih banyak bangsawan untuk ikut serta dalam rencananya—",
  ui_story_5011_50111302_55X2_dialog_content = "Bergabunglah dengan Eclipse yang mulia—dapatkan kekuatan tanpa batas melalui transformasi.",
  ui_story_5011_50111302_55X3_dialog_content = "Dapatkan kesempatan untuk memperoleh umur panjang dan menambah kekuatanmu dengan tubuh hasil transformasi.",
  ui_story_5011_50111302_55X4_dialog_content = "Ahahaha! Saat itulah aku memperoleh kekuatan baru!",
  ui_story_5011_50111302_55X5_dialog_content = "Tapi sayangnya, sebelum mereka berhasil, Lumopolis berhasil menumpas mereka.",
  ui_story_5011_50111302_55X6_dialog_content = "Yang Mulia, coba katakan kepadaku... Wajar saja kalau dia jadi benci kepada Lumopolis, 'kan?",
  ui_story_5011_50111302_55X7_dialog_content = "Wajar saja 'kan kalau dia bertindak senekat itu?",
  ui_story_5011_50111302_55X8_dialog_content = "Rupanya begitu... Rupanya begitulah terjadinya Pemberontakan Lumopolis...",
  ui_story_5011_50111302_55X9_dialog_content = "Paloma...",
  ui_story_5011_50111302_55X10_dialog_content = "Diam! Jangan menyela ceritaku!",
  ui_story_5011_50111302_55X11_dialog_content = "Akan kuberi kau satu kesempatan terakhir untuk menceritakan semuanya kepada kami.",
  ui_story_5011_50111302_55X12_dialog_content = "Tidak, tidak, tidak—kalau itu maumu, berarti ceritaku cukup sampai di sini saja.",
  ui_story_5011_50111302_56_dialog_content = "Yang Mulia, apa kau suka ceritanya?",
  ui_story_5011_50111302_57_dialog_content = "Apa kau bisa bersimpati dengan tokoh utamanya?",
  ui_story_5011_50111302_58_dialog_content = "Atau, apa kau ingin menanyakan detailnya kepada si tokoh utama itu sendiri, Lord Lachon?",
  ui_story_5011_50111302_59_dialog_content = "Aku lebih suka mengakhiri ceritamu saja. Selamanya.",
  ui_story_5011_50111302_60_dialog_content = "Ck, ck, ck! Sudah lama aku tak menikmati kelakar seperti itu! Kurasa kita berdua bisa akrab!",
  ui_story_5011_50111302_61_dialog_content = "Tapi, sayangnya, sekarang saatnya kita berpisah.",
  ui_story_5011_50111302_62_dialog_content = "Mirren!",
  ui_story_5011_50111302_63_dialog_content = "Argh... Aku masih bisa...",
  ui_story_5011_50111302_64_dialog_content = "Kita kembalikan panggungnya kepada tokoh utama hari ini...",
  ui_story_5011_50111302_65_dialog_content = "Dia... Lagi-lagi dia menghilang tanpa jejak!",
  ui_story_5011_50111302_66_dialog_content = "Dia menggunakan Eclipsium khusus yang katanya bisa memanipulasi dimensi ruang.",
  ui_story_5011_50111302_67_dialog_content = "Dari dulu, Mirren memang lihai dalam urusan kabur... Dia pasti sudah jutaan kali kabur seperti ini.",
  ui_story_5011_50111302_68_dialog_content = "Kau harus istirahat dan membiarkan kebencianmu mereda untuk sementara waktu.",
  ui_story_5011_50111302_69_dialog_content = "Sekarang, kau bisa tangani pria bernama Lachon itu.",
  ui_story_5011_50111302_70_dialog_content = "Figerald... Hah... Inilah yang namanya perlakuan tak adil.",
  ui_story_5011_50111302_71_dialog_content = "Pada akhirnya, lagi-lagi aku ditinggalkan...",
  ui_story_5011_50111302_72_dialog_content = "Kalau memang begitu, akan kuterima nasibku.",
  ui_story_5011_50111302_73_dialog_content = "Apa aku akan dieksekusi di hadapan publik? Atau disidang di pengadilan?",
  ui_story_5011_50111302_74_dialog_content = "Atau mungkin aku akan diusir?",
  ui_story_5011_50111302_74X1_dialog_content = "Dikirim ke Heretics Investigation Division dalam wujud Eclipsite mungkin adalah pilihan bagus untukmu.",
  ui_story_5011_50111302_75_dialog_content = "Heretics Investigation Division dari Gereja akan memutuskan hukuman yang sesuai untukmu.",
  ui_story_5011_50111302_76_dialog_content = "Lachon.",
  ui_story_5011_50111401_1_dialog_content = "Hedy, akhirnya kau berhasil! Bagaimana jadinya?",
  ui_story_5011_50111401_2_dialog_content = "Sudah selesai.",
  ui_story_5011_50111401_3_dialog_content = "Bisa tolong jelaskan...?",
  ui_story_5011_50111401_4_dialog_content = "Michelangelo tiba-tiba saja menghilang... seperti Mirren barusan.",
  ui_story_5011_50111401_5_dialog_content = "Baru saja, Mirren kabur dengan menggunakan Eclipsium.",
  ui_story_5011_50111401_5X1_dialog_content = "Apa itu semacam Eclipsium ruang?",
  ui_story_5011_50111401_5X2_dialog_content = "Itulah yang diyakini Yang Mulia.",
  ui_story_5011_50111401_6_dialog_content = "Ada juga seseorang bernama Figerald di sini, tapi lagi-lagi berkat Yang Mulia...",
  ui_story_5011_50111401_6X1_dialog_content = "Kita bisa bahas detailnya belakangan.",
  ui_story_5011_50111401_7_dialog_content = "Kita urus dulu si pengkhianat itu.",
  ui_story_5011_50111401_8_dialog_content = "Michelangelo... Apa bocah itu berhasil lolos?",
  ui_story_5011_50111401_9_dialog_content = "Kalau begitu, tak ada yang perlu kukhawatirkan.",
  ui_story_5011_50111401_10_dialog_content = "Kau, Lachon, seorang bangsawan... berani-beraninya kau mengkhianati Lumopolis?",
  ui_story_5011_50111401_11_dialog_content = "Apa pembelaanmu?",
  ui_story_5011_50111401_12_dialog_content = "Hmm... Kau ingin tahu kenapa aku, seorang bangsawan, mengkhianati Lumopolis?",
  ui_story_5011_50111401_13_dialog_content = "Apa yang kudapat dari statusku sebagai bangsawan?",
  ui_story_5011_50111401_14_dialog_content = "Istana kosong? Garis keturunan tanpa masa depan? Bagaimana dengan hinaan dari City Lord?",
  ui_story_5011_50111401_15_dialog_content = "Dan hidup yang benar-benar gagal dan tak punya harapan...",
  ui_story_5011_50111401_15X1_dialog_content = "Pengorbanan anak-anakmu demi Lumopolis adalah hal yang adil dan mulia.",
  ui_story_5011_50111401_15X2_dialog_content = "Tapi, perbuatanmu justru menodai kehormatan mereka!",
  ui_story_5011_50111401_15X3_dialog_content = "Rupanya itu maksud Figerald saat dia bilang \"kau memberikan segalanya demi Lumopolis\"...",
  ui_story_5011_50111401_15X4_dialog_content = "Tapi, kau tak paham bahwa pada akhirnya, kejayaan dan keadilan tak ada artinya!",
  ui_story_5011_50111401_15X5_dialog_content = "Tidak, kau berkubang dalam buah kejayaan dan keadilan...",
  ui_story_5011_50111401_15X6_dialog_content = "Lumopolis sudah memberimu segalanya—",
  ui_story_5011_50111401_16_dialog_content = "Kau sudah punya semua kuasa, status, dan kekayaan sesuai keinginanmu. Apa kau belum puas?",
  ui_story_5011_50111401_17_dialog_content = "Puas? Sebentar lagi hidupku berakhir. Sebentar lagi aku akan kehilangan segalanya... Mana bisa aku merasa puas!?",
  ui_story_5011_50111401_18_dialog_content = "Aku terlena oleh nafsu tiada akhir.",
  ui_story_5011_50111401_19_dialog_content = "Tentu saja, aku harus langsung membawamu kembali ke gereja...",
  ui_story_5011_50111401_20_dialog_content = "Tidak, tak akan kubiarkan kau menjadikanku bahan eksperimen!",
  ui_story_5011_50111401_21_dialog_content = "Lihat ini? Enhancer merah ini sepertinya berdenyut.",
  ui_story_5011_50111401_22_dialog_content = "Penuh kehidupan, penuh kemungkinan tak terbatas...",
  ui_story_5011_50111401_23_dialog_content = "Tapi, kekuatan ini hanyalah ilusi.",
  ui_story_5011_50111401_24_dialog_content = "Setelah meminum benda ini, hanya ada satu kemungkinan... Yaitu berubah menjadi Eclipsite.",
  ui_story_5011_50111401_25_dialog_content = "Kita semua sudah pernah melihatnya.",
  ui_story_5011_50111401_26_dialog_content = "Tidak, kau tak paham.",
  ui_story_5011_50111401_27_dialog_content = "Sejak prototipenya keluar dari <color=#FFB400>Illumina Lab</color>, aku sudah mengamatinya...",
  ui_story_5011_50111401_28_dialog_content = "...!?",
  ui_story_5011_50111401_29_dialog_content = "Tunggu... Apa maksudmu?",
  ui_story_5011_50111401_30_dialog_content = "Haha, kalian semua kaget, ya?",
  ui_story_5011_50111401_31_dialog_content = "Dunia ini adalah tempat yang sangat kompleks. Kita semua butuh harapan yang sederhana dan sempurna.",
  ui_story_5011_50111401_32_dialog_content = "Atau... mungkin keputusasaan...?",
  ui_story_5011_50111401_33_dialog_content = "Jelaskan! Apa hubungannya ini dengan Illumina!?",
  ui_story_5011_50111401_34_dialog_content = "Tenangkan dirimu, Vice! Jangan dengarkan kebohongannya!",
  ui_story_5011_50111401_35_dialog_content = "Kau tahu apa yang kumaksud. Aku tahu... Dalam lubuk hati, kalian semua tahu.",
  ui_story_5011_50111401_36_dialog_content = "*glek*",
  ui_story_5011_50111401_37_dialog_content = "Dia... menelannya.",
  ui_story_5011_50111401_38_dialog_content = "...",
  ui_story_5011_50111401_39_dialog_content = "Heh...",
  ui_story_5011_50111401_40_dialog_content = "Urk...",
  ui_story_5011_50111401_41_dialog_content = "Kukira rasanya akan lebih sakit...",
  ui_story_5011_50111401_42_dialog_content = "Apa ini saatnya untukku...?",
  ui_story_5011_50111401_43_dialog_content = "Schwartz... Sayang sekali kau tak ada di sini untuk melihatnya...",
  ui_story_5011_50111401_44_dialog_content = "<anim type=Shake>...</anim>",
  ui_story_5011_50111401_45_dialog_content = "Lachon...",
  ui_story_5011_50111401_46_dialog_content = "Dia sudah tak ada di sana lagi...",
  ui_story_5011_50111401_47_dialog_content = "<anim type=Shake>...</anim>",
  ui_story_5011_50111401_48_dialog_content = "PlayerName.",
  ui_story_5011_50111401_49_dialog_content = "Aku paham, Yang Mulia.",
  ui_story_5011_50111401_50_dialog_content = "Ayo... kita akhiri semua ini.",
  ui_story_5011_50111402_1_dialog_content = "...",
  ui_story_5011_50111402_2_dialog_content = "Pada akhirnya, dia tetap tak bisa lari dari kematian.",
  ui_story_5011_50111402_3_dialog_content = "Kematian adalah obsesinya.",
  ui_story_5011_50111402_4_dialog_content = "Tapi... Aku masih bisa merasakan keinginan kuat untuk bertahan hidup.",
  ui_story_5011_50111402_5_dialog_content = "Kedua hal itu saling berkaitan.",
  ui_story_5011_50111402_6_dialog_content = "Tanpa nafsu, tak mungkin ada orang yang mau bergabung dengan Eclipse.",
  ui_story_5011_50111402_7_dialog_content = "Eclipse memang paling lihai memanipulasi hati dan pikiran manusia.",
  ui_story_5011_50111402_8_dialog_content = "...",
  ui_story_5011_50111402_9_dialog_content = "Kau tidak sedang membelanya, 'kan?",
  ui_story_5011_50111402_10_dialog_content = "Aku hanya memikirkan kata-katanya yang belum selesai itu. Tentang...",
  ui_story_5011_50111402_11_dialog_content = "Illumina.",
  ui_story_5011_50111402_12_dialog_content = "Aku sama sekali tak heran...",
  ui_story_5011_50111402_13_dialog_content = "Apa kau punya sampel obat itu?",
  ui_story_5011_50111402_14_dialog_content = "Kalau butuh sampel, bukankah lebih baik kau langsung menanyakannya kepada Illumina?",
  ui_story_5011_50111402_15_dialog_content = "Pittman! Kukira kita ini bekerja sama!",
  ui_story_5011_50111402_16_dialog_content = "Naif sekali...",
  ui_story_5011_50111402_17_dialog_content = "Hentikan... Berhentilah berdebat. Inilah yang diinginkan Eclipse...",
  ui_story_5011_50111402_18_dialog_content = "Kekacauan. Akibat nafsu, mereka berusaha terus-menerus membuat kita bingung...",
  ui_story_5011_50111402_19_dialog_content = "Yang lainnya boleh saja goyah, tapi kita tak boleh. Hanya kitalah yang bisa mengungkap kebenarannya.",
  ui_story_5011_50111402_20_dialog_content = "Tapi, semua orang berhak mengetahui kebenarannya.",
  ui_story_5011_50111402_21_dialog_content = "Dalam kondisi saat ini, Illumina dan Gereja tahu lebih banyak daripada kita...",
  ui_story_5011_50111402_22_dialog_content = "Daripada berdebat, bagaimana kalau kita pikirkan apa yang akan kita lakukan setelah ini...",
  ui_story_5011_50111402_23_dialog_content = "PlayerName, apa kau mau bilang sesuatu?",
  ui_story_5011_50111402_24_dialog_content = "Aku sudah mengatakan semuanya. Aku masih berusaha melacak posisi Figerald, tapi tak ada hasilnya.",
  ui_story_5011_50111402_25_dialog_content = "Nama terkutuk itu... Figerald.",
  ui_story_5011_50111402_26_dialog_content = "Kapten Carleen.",
  ui_story_5011_50111402_27_dialog_content = "Ada apa? Bagaimana situasi di distrik bangsawan?",
  ui_story_5011_50111402_28_dialog_content = "Saat insiden itu terjadi, semua orang langsung dievakuasi secepatnya, lebih cepat dari perkiraan kami...",
  ui_story_5011_50111402_29_dialog_content = "Seakan-akan mereka sudah tahu lebih dulu.",
  ui_story_5011_50111402_30_dialog_content = "...",
  ui_story_5011_50111402_31_dialog_content = "Aku mengerti.",
  ui_story_5011_50111402_32_dialog_content = "Serahkan saja kepada Lumopolis. Kurasa masih banyak bukti yang harus kaukumpulkan.",
  ui_story_5011_50111402_33_dialog_content = "Memang. Begitu, 'kan, Pittman?",
  ui_story_5011_50111402_34_dialog_content = "... Benar.",
  ui_story_5011_50111402_35_dialog_content = "Paloma harus ikut denganku. Aku punya beberapa pertanyaan...",
  ui_story_5011_50111402_36_dialog_content = "Maaf, Hedy. Aku tak mau ikut siapa pun. Aku sudah muak dengan semua ini.",
  ui_story_5011_50111402_36X1_dialog_content = "Dia kabur terburu-buru...",
  ui_story_5011_50111402_36X2_dialog_content = "Sudahlah. Saat ini ada masalah yang lebih mendesak. Lain kali...",
  ui_story_5011_50111402_37_dialog_content = "Bethlehem, Yang Mulia! Akhirnya aku menemukan Anda... Bagaimana Anda bisa sampai ke sini...?",
  ui_story_5011_50111402_38_dialog_content = "City Lord mendesak lagi untuk bertemu dengan kita. Anda harus segera menemuinya...",
  ui_story_5011_50111402_39_dialog_content = "Seperti yang kaulihat, urusanku di sini baru saja selesai.",
  ui_story_5011_50111402_40_dialog_content = "PlayerName.",
  ui_story_5011_50111402_41_dialog_content = "... Ya!",
  ui_story_5011_50111402_42_dialog_content = "Lumopolis mengundangmu untuk menghadiri perayaan itu.",
  ui_story_5011_50111402_43_dialog_content = "Benar... Tapi, aku tak paham maksud Anda.",
  ui_story_5011_50111402_44_dialog_content = "Jangan berdiri kebingungan saja di sana.",
  ui_story_5011_50111402_45_dialog_content = "Kau juga ikut ke aula perayaan.",
  ui_story_5011_50111402_46_dialog_content = "Hahaha! Lord Figerald, kita berhasil lolos!",
  ui_story_5011_50111402_47_dialog_content = "Udara di luar Lumopolis terasa sungguh segar.",
  ui_story_5011_50111402_48_dialog_content = "Lepaskan aku!",
  ui_story_5011_50111402_49_dialog_content = "Bocah lelaki ini melawan cukup keras... Tidakkah kau ingin mengikuti Lord Figerald?",
  ui_story_5011_50111402_50_dialog_content = "Aku ingin kembali untuk menyelamatkan Lord Lachon!",
  ui_story_5011_50111402_51_dialog_content = "Tapi, Lord Lachon-mu itu mungkin sekarang sudah jadi seonggok debu! Ck, ck, ck!",
  ui_story_5011_50111402_52_dialog_content = "Kau mengkhianatinya!",
  ui_story_5011_50111402_53_dialog_content = "Kau mengarahkan Mirren ke istana Lord Lachon hanya agar orang-orang itu bisa mengejarnya ke sana!",
  ui_story_5011_50111402_54_dialog_content = "Obat yang kauberikan kepada Lord Lachon... Belum utuh, 'kan!?",
  ui_story_5011_50111402_55_dialog_content = "Apa maksud semua ini!?",
  ui_story_5011_50111402_56_dialog_content = "Kalau kau ingin bekerja sama dengan Eclipse, kau harus benar-benar siap menanggung risiko dan konsekuensinya!",
  ui_story_5011_50111402_57_dialog_content = "Lachon tahu apa yang dihadapinya. Dia tak butuh orang tak berharga sepertimu untuk membela kehormatannya.",
  ui_story_5011_50111402_58_dialog_content = "Awalnya, kami ingin menampakkan diri dengan meriah saat perayaan itu.",
  ui_story_5011_50111402_59_dialog_content = "Tapi, Lord Lachon-mu itu... Berani-beraninya dia menentangku!",
  ui_story_5011_50111402_60_dialog_content = "Lachon... Pria tua bangka itu pasti jadi paranoid gara-gara insiden Umbraton itu!",
  ui_story_5011_50111402_61_dialog_content = "Diam! Jangan berani-berani menghina Lord Lachon!",
  ui_story_5011_50111402_62_dialog_content = "Yeaargh!",
  ui_story_5011_50111402_63_dialog_content = "Berani-beraninya kau memukulku!?",
  ui_story_5011_50111402_64_dialog_content = "Lord Figerald, Michelangelo pergi!",
  ui_story_5011_50111402_65_dialog_content = "Apa kita perlu mengejarnya?",
  ui_story_5011_50111402_66_dialog_content = "Ayo kita kejar bocah lelaki itu dan siksa dia pelan-pelan sampai mati...",
  ui_story_5011_50111402_67_dialog_content = "Tak perlu.",
  ui_story_5011_50111402_68_dialog_content = "Dia akan kembali.",
  ui_story_5011_50111402_69_dialog_content = "Karena hanya kitalah teman sejatinya.",
  ui_story_5011_50111501_1_dialog_content = "Jadi, pemberontakan di Umbraton itu adalah ulah Lachon dan Eclipse?",
  ui_story_5011_50111501_2_dialog_content = "Ya, Ayah.",
  ui_story_5011_50111501_3_dialog_content = "Selain itu, pemberontakan keluarga Pyrrhus dan Gautier juga kemungkinan besar berhubungan dengan Lachon.",
  ui_story_5011_50111501_4_dialog_content = "Metode transformasi keluarga Pyrrhus yang digunakan pada Beryl, serta transformasi Mirren Gautier yang digunakannya demi membalas dendam...",
  ui_story_5011_50111501_5_dialog_content = "Sepertinya, sumber semua ini adalah Lachon dan Eclipse.",
  ui_story_5011_50111501_6_dialog_content = "Hmm...",
  ui_story_5011_50111501_7_dialog_content = "Mereka berusaha menimbulkan kekacauan di Umbraton, membunuh Istvan, dan kemudian memanfaatkan antek Lachon untuk mengendalikan seluruh Umbraton. Lalu...",
  ui_story_5011_50111501_8_dialog_content = "Dengan begitu, mereka akan bisa memanfaatkan Umbraton sebagai benteng dan menyerang Lumopolis sewaktu-waktu.",
  ui_story_5011_50111501_9_dialog_content = "Oh... Tidak, aku khawatir bahwa target Eclipse bukanlah Lumopolis semata.",
  ui_story_5011_50111501_10_dialog_content = "Ayah, aku benar-benar tak bisa memahami semua yang telah dilakukan Lachon dalam sepuluh tahun belakangan ini.",
  ui_story_5011_50111501_11_dialog_content = "Makin besar kekuatan, makin besar pula nafsu untuk mendapatkan kekuatan yang lebih... Dan, makin tua, kita jadi makin takut menghadapi kematian.",
  ui_story_5011_50111501_12_dialog_content = "Aku bisa memahami apa yang dirasakan Lachon.",
  ui_story_5011_50111501_13_dialog_content = "Ayah, apa kita sebaiknya segera memulai ulang penyelidikan tentang pemberontakan itu, untuk mengembalikan nama baik para korban dan...",
  ui_story_5011_50111501_14_dialog_content = "Tidak. Kalau kita kembali menggali masalah ini, yang akan muncul hanyalah lebih banyak masalah bagi semua orang yang terlibat, dan pamor kalangan bangsawan Lumopolis akan terancam bahaya.",
  ui_story_5011_50111501_15_dialog_content = "Bahkan kebenaran tentang insiden Lachon ini pun sebisa mungkin harus disamarkan.",
  ui_story_5011_50111501_16_dialog_content = "Ingat, tak ada yang lebih penting daripada menjaga ketertiban!",
  ui_story_5011_50111501_17_dialog_content = "Yang harus kaulakukan sekarang adalah menambah sumber daya pengawasan untuk memantau kalangan bangsawan, agar insiden seperti ini tak terulang.",
  ui_story_5011_50111501_18_dialog_content = "Kalau kita menggali-gali masa lalu, keadaan akan jadi makin sulit untuk semua orang.",
  ui_story_5011_50111501_19_dialog_content = "Ini perintah.",
  ui_story_5011_50111501_20_dialog_content = "... Ya, Ayah.",
  ui_story_5011_50111501_21_dialog_content = "Aulanya sungguh luas... Sangat berbeda dibandingkan di Illumina...",
  ui_story_5011_50111501_22_dialog_content = "Oh, lagi-lagi aku melamun.",
  ui_story_5011_50111501_23_dialog_content = "... Dan demikianlah ringkasanku tentang peristiwa yang terjadi di Umbraton, Lower Lumopolis, dan distrik bangsawan.",
  ui_story_5011_50111501_24_dialog_content = "Seluruh proses penyelidikan ini... banyak dibantu oleh Hedy, seorang pakar dari Heretics Investigation Division... Setelah ini...",
  ui_story_5011_50111501_25_dialog_content = "Maaf menyela, tapi aku ingin bertanya.",
  ui_story_5011_50111501_26_dialog_content = "Siapa yang bertanggung jawab atas semua insiden itu?",
  ui_story_5011_50111501_27_dialog_content = "Jelas bahwa Lachon dan Eclipse-lah dalang di balik insiden itu.",
  ui_story_5011_50111501_28_dialog_content = "Semua tragedi ini disebabkan oleh nafsu Lachon untuk memperoleh kekuatan dan umur panjang.",
  ui_story_5011_50111501_29_dialog_content = "Lachon sudah mati, dan kita akan terus mengejar Mirren Gautier, Michelangelo, dan para pelaku lainnya.",
  ui_story_5011_50111501_30_dialog_content = "Upaya melawan Eclipse akan terus berlanjut, dan suatu saat nanti semua masalah ini akan berakhir.",
  ui_story_5011_50111501_31_dialog_content = "Bukankah kebenaran di balik pemberontakan ini perlu diselidiki?",
  ui_story_5011_50111501_32_dialog_content = "Bukankah Beryl, Paloma, dan bahkan kau, Pittman, pantas mendapatkan kebenaran dan keadilan yang kalian cari-cari?",
  ui_story_5011_50111501_33_dialog_content = "Kami tak perlu memberimu informasi khusus tentang urusan Lumopolis, PlayerName.",
  ui_story_5011_50111501_34_dialog_content = "Tentu saja, aku bisa berjanji untuk memperkuat pengelolaan dan pemantauan kalangan bangsawan Lumopolis untuk ke depannya, guna memastikan bahwa insiden ini tak terulang...",
  ui_story_5011_50111501_35_dialog_content = "Prinsip-prinsip megah itu sekali lagi diberlakukan.",
  ui_story_5011_50111501_36_dialog_content = "Baiklah. Tapi, aku ingin tahu, bagaimana kita bisa menangani masalah Enhancer dan dampak dari transformasi ini?",
  ui_story_5011_50111501_37_dialog_content = "Dampak? Kenapa kita harus menangani dampaknya?",
  ui_story_5011_50111501_38_dialog_content = "Apa!? Bagaimana dengan para korban?",
  ui_story_5011_50111501_39_dialog_content = "PlayerName, Enhancer dan transformasi yang dihasilkannya dikembangkan oleh Illumina. Lebih baik kau langsung menanyakannya kepada Reinhardt.",
  ui_story_5011_50111501_40_dialog_content = "Nah, Lord Reinhardt, apakah Enhancer dan teknik transformasi itu memang dikembangkan oleh Illumina?",
  ui_story_5011_50111501_41_dialog_content = "...",
  ui_story_5011_50111501_42_dialog_content = "Berdasarkan informasi dari tim penyelidik, aku yakin antek Eclipse itu bicara jujur.",
  ui_story_5011_50111501_43_dialog_content = "Kedua teknologi itu adalah hasil dari <color=#FFB400>eksperimen</color> yang dilakukan oleh Illumina bertahun-tahun lalu, tetapi hal itu sengaja ditutup-tutupi.",
  ui_story_5011_50111501_44_dialog_content = "Lebih tepatnya, eksperimen itu ditinggalkan karena gagal menciptakan pasukan super yang stabil dan bisa dikendalikan.",
  ui_story_5011_50111501_45_dialog_content = "Tentang bagaimana obat itu bisa jatuh ke tangan Eclipse, kita hanya bisa menanyakannya kepada pemimpin Illumina.",
  ui_story_5011_50111501_46_dialog_content = "Pertanyaan tak penting.",
  ui_story_5011_50111501_47_dialog_content = "Tak penting? Teknologi tak beradab seperti itu tak boleh ada di dunia ini!",
  ui_story_5011_50111501_48_dialog_content = "Dan kalau teknologi yang mampu menciptakan pasukan super secara massal itu sampai ada...",
  ui_story_5011_50111501_49_dialog_content = "Berapa banyak lagi pertarungan yang harus kita menangi? Berapa banyak lagi prajurit yang harus menanggung nasib suram di medan tempur?",
  ui_story_5011_50111501_50_dialog_content = "PlayerName... Kau masih ingat Dunefire Line, 'kan?",
  ui_story_5011_50111501_51_dialog_content = "Seandainya ada ribuan atau puluhan ribu prajurit di Undercity 24, apa menurutmu Brent akan mati?",
  ui_story_5011_50111501_52_dialog_content = "Bagaimana kalau kita bisa punya ratusan ribu, atau bahkan jutaan, prajurit super?",
  ui_story_5011_50111501_53_dialog_content = "Apa kita masih perlu mempertahankan barisan? Kita pasti akan bisa mengungguli Eclipsite.",
  ui_story_5011_50111501_54_dialog_content = "Aku...",
  ui_story_5011_50111501_55_dialog_content = "Hahaha... Lord Reinhardt, aku dan kau sama-sama paham...",
  ui_story_5011_50111501_56_dialog_content = "Kalau Illumina memang menciptakan prajurit super, aku khawatir hal pertama yang akan kaulakukan bukanlah mengalahkan Eclipsite.",
  ui_story_5011_50111501_57_dialog_content = "Sama saja denganmu, City Lord.",
  ui_story_5011_50111501_58_dialog_content = "Ada hal-hal tertentu yang tak butuh ratusan ribu prajurit super.",
  ui_story_5011_50111501_59_dialog_content = "Oh, masa? Nah, bagaimana kalau kaucoba saja dan kita lihat bagaimana jadinya?",
  ui_story_5011_50111501_60_dialog_content = "Lord Reinhardt, apa Illumina mengembangkan senjata rahasia lagi?",
  ui_story_5011_50111501_61_dialog_content = "Bisakah kau bersikap masa bodoh terhadap konsekuensinya?",
  ui_story_5011_50111501_62_dialog_content = "Konsekuensi? Seandainya kita gagal dalam upaya itu...",
  ui_story_5011_50111501_63_dialog_content = "Pria wanita, tua muda, semuanya akan jadi mangsa Eclipsite. Ada yang mau bergabung dengan kami?",
  ui_story_5011_50111501_64_dialog_content = "Illumina sudah tahu kebenarannya—bahwa kita hanya bisa mengandalkan diri kita sendiri—dari para petinggi Lumopolis sejak dulu.",
  ui_story_5011_50111501_65_dialog_content = "Topik ini sudah tak perlu dibahas lebih lanjut lagi hari ini. Sebaiknya kalian tetap tenang.",
  ui_story_5011_50111501_66_dialog_content = "Kita bisa menyelami masa lalu nanti saja...",
  ui_story_5011_50111501_67_dialog_content = "Tapi, bukankah sekarang kita seharusnya mencari cara untuk membantu orang-orang yang sudah terlanjur menelan Enhancer dan bertransformasi?",
  ui_story_5011_50111501_68_dialog_content = "Yang Mulia, siapa pun yang membuat atau mengujicobakannya...",
  ui_story_5011_50111501_69_dialog_content = "Kalian semua, Investigation Division dari Gereja, Illumina Research Center, dan Umbraton Medical Academy siap membantu... Tidak bisakah kita coba cari cara?",
  ui_story_5011_50111501_70_dialog_content = "...",
  ui_story_5011_50111501_71_dialog_content = "...",
  ui_story_5011_50111501_72_dialog_content = "Aku khawatir masalah ini tak bisa diselesaikan sekarang. Kalau tidak, mestinya masalah ini sudah selesai dari dulu.",
  ui_story_5011_50111501_73_dialog_content = "Kami akan menyelidiki kasus Enhancer dan teknik modifikasi ini secara menyeluruh agar tidak menyebar lebih jauh.",
  ui_story_5011_50111501_74_dialog_content = "Kami juga berharap bisa bekerja sama dengan Lumopolis untuk menyelidiki hal ini.",
  ui_story_5011_50111501_75_dialog_content = "Bagus. Dengan ini kunyatakan bahwa Lumopolis akan memberikan dukungan penuh.",
  ui_story_5011_50111501_76_dialog_content = "Yah... Bagaimanapun, aku tak bisa terima kalau kita harus berubah menjadi Eclipsite agar bisa mengalahkan Eclipsite!",
  ui_story_5011_50111501_77_dialog_content = "Aduh... Pengap sekali di sini. Aku mau jalan-jalan keluar.",
  ui_story_5011_50111501_78_dialog_content = "Tapi, perayaannya akan segera dimulai.",
  ui_story_5011_50111501_79_dialog_content = "Teman-temanku yang terhormat, aku permisi dulu.",
  ui_story_5011_50111501_80_dialog_content = "PlayerName...",
  ui_story_5011_50111501_81_dialog_content = "Hedy, sedang apa kau di sini?",
  ui_story_5011_50111501_82_dialog_content = "Kita tak boleh berubah menjadi Eclipsite untuk mengalahkan Eclipsite... Aku setuju denganmu tentang hal ini.",
  ui_story_5011_50111501_83_dialog_content = "Begitulah menurutku. Ada banyak tindakan para pemimpin itu yang tak sesuai dengan pandanganku.",
  ui_story_5011_50111501_84_dialog_content = "Tapi, kau berharap bisa menemukan pengobatan untuk mengatasi Enhancer dan teknik modifikasi itu. Itu tak akan bisa mengatasi masalah ini.",
  ui_story_5011_50111501_85_dialog_content = "Hah? Kenapa tidak?",
  ui_story_5011_50111501_86_dialog_content = "Teknologi yang baru muncul ini tidak hanya membawa kekuatan besar, tetapi juga kesengsaraan dan kematian.",
  ui_story_5011_50111501_87_dialog_content = "Tapi, begitu teknologi ini sudah lengkap, baik kesengsaraan maupun kematian tak akan bisa menghentikan niat buruk dan orang-orang yang haus kekuatan itu.",
  ui_story_5011_50111501_88_dialog_content = "Dan, kalau teknologi itu sampai jadi lengkap... Yah, kau bisa menduga apa yang akan dilakukan pihak-pihak berniat buruk itu untuk mencapai ambisi mereka.",
  ui_story_5011_50111501_89_dialog_content = "Dan saat itu terjadi, apa jadinya dunia kita nanti?",
  ui_story_5011_50111501_90_dialog_content = "Uh...",
  ui_story_5011_50111501_91_dialog_content = "Karenanya, satu-satunya solusi yang masuk akal adalah menghancurkan teknologi itu untuk selamanya.",
  ui_story_5011_50111501_92_dialog_content = "Selama teknologi semacam itu masih ada, nafsu tanpa batas akan terus mendorong orang-orang untuk berkonspirasi.",
  ui_story_5011_50111501_93_dialog_content = "Dan, jurang yang tercipta akibat konspirasi mereka akan penuh dengan mayat para korban.",
  ui_story_5011_50111501_94_dialog_content = "Itu tentu bukan masa depan yang ingin kita lihat.",
  ui_story_5011_50111501_95_dialog_content = "Tapi Paloma... Beryl... Bagaimana dengan mereka?",
  ui_story_5011_50111501_96_dialog_content = "Biarlah mereka menutup lembaran gelap dalam hidup mereka itu.",
  ui_story_5011_50111501_97_dialog_content = "Kalau kita bersatu dan berhasil membasmi para Eclipsite untuk selamanya, apakah semuanya akan baik-baik saja?",
  ui_story_5011_50111501_98_dialog_content = "Bersatu? Tidak semua orang sama sepertimu...",
  ui_story_5011_50111501_99_dialog_content = "Dibandingkan dengan ancaman dari Eclipsite, aku lebih khawatir tentang kebobrokan di tengah kaum Aurorian...",
  ui_story_5011_50111501_100_dialog_content = "PlayerName, perayaannya akan segera dimulai!",
  ui_story_5011_50111501_101_dialog_content = "Baiklah kalau begitu, PlayerName, sebaiknya sekarang kau segera menyusul.",
  ui_story_5011_50111501_102_dialog_content = "Kau akan melihat para Aurorian <color=#FFB400>bersatu</color> dalam pesta ini, persis seperti harapanmu.",
  ui_story_5011_50111501_103_dialog_content = "Perayaannya sudah dimulai.",
  ui_story_5011_50111501_104_dialog_content = "<anim type=Shake><size=45>Ohhhhhh!!!</size></anim>",
  ui_story_5011_50111501_105_dialog_content = "Sang City Lord! Sang City Lord!",
  ui_story_5011_50111501_106_dialog_content = "Apa itu Reinhardt?",
  ui_story_5011_50111501_107_dialog_content = "Itu Grand Marshal! Tolong hormati beliau!",
  ui_story_5011_50111501_108_dialog_content = "Silakan.",
  ui_story_5011_50111501_109_dialog_content = "Mari, City Lord. Andalah pemimpin Lumopolis.",
  ui_story_5011_50111501_110_dialog_content = "Terima kasih.",
  ui_story_5011_50111501_111_dialog_content = "Wargaku yang dinaungi kemuliaan Aurora.",
  ui_story_5011_50111501_112_dialog_content = "Hari ini hari biasa, sama saja seperti hari-hari lainnya. Matahari masih bergantung tinggi di langit.",
  ui_story_5011_50111501_113_dialog_content = "Kita masih berdiri di benteng yang dibangun oleh para leluhur kita dengan darah dan keyakinan.",
  ui_story_5011_50111501_114_dialog_content = "Kita masih hidup di balik tembok yang melindungi kita dari kegelapan.",
  ui_story_5011_50111501_115_dialog_content = "Kita masih berlindung di bawah naungan Aurora yang abadi.",
  ui_story_5011_50111501_116_dialog_content = "Dan demikianlah, kita merayakan peradaban kita yang berumur panjang! Kita mengenang semua pahlawan yang telah berjuang untuk mewujudkannya dengan darah, keringat, air mata, dan nyawa mereka!",
  ui_story_5011_50111501_117_dialog_content = "Kukaruniakan kemuliaan mereka kepada kalian semua—medali agung perlambang kehormatan dan kewajiban... untuk terus bersama-sama memajukan peradaban Aurorian!",
  ui_story_5011_50111501_118_dialog_content = "Biarlah suara persatuan kita menggelegar di langit dan membelah malam—",
  ui_story_5011_50111501_119_dialog_content = "<size=45><color=#FFB400>Aurora Aeterna—!</color></size>"
}
return config
